1	import { Client, type ClientChannel, type SFTPWrapper } from "ssh2";
2	import { connectionTarget, serverRootPassword } from "../lib/sftp";
3	import { decryptSecret } from "../lib/crypto-box";
4	
5	/**
6	 * SECURE real cross-provider migration engine (gated behind ENABLE_REAL_MIGRATION).
7	 *
8	 * This replaces the earlier, REVERTED implementation that built shell command
9	 * strings out of customer-supplied DB names / users / paths and ran them as root
10	 * over SSH — a shell-injection / RCE hole. This version is hardened on two axes:
11	 *
12	 *   1. STRICT ALLOWLIST VALIDATION. Every non-secret input (source host, port,
13	 *      user, file paths, DB engine/name/user) must match a shell-inert allowlist
14	 *      regex or the migration FAILS. We reject — never sanitize. The permitted
15	 *      charsets contain no shell metacharacters, so even though validated values
16	 *      are interpolated into command strings, there is no injection surface.
17	 *
18	 *   2. SECRETS NEVER TOUCH A COMMAND STRING. The source SSH password is written
19	 *      to a 0600 file on the target over the SFTP channel (bytes, not a shell
20	 *      arg) and consumed with `sshpass -f`. Source DB passwords are written into
21	 *      a defaults-extra-file (MySQL) / .pgpass (Postgres) on the source by
22	 *      streaming the file body through the command's STDIN — again never as an
23	 *      argv token. Command strings reference only file PATHS.
24	 *
25	 * Scope (v1): files are pulled directly (rsync) into a staging dir on the target;
26	 * databases are DUMPED into that staging dir (no auto-import — we don't assume the
27	 * target's DB layout/users, which would be fragile and risky). The customer is
28	 * told exactly where everything landed and how to finish. All work is confined to
29	 * a per-migration work dir; system paths are never overwritten.
30	 *
31	 * Every secret is used in-memory only and scrubbed from disk in a finally block.
32	 */
33	
34	type ReportFn = (progress: number, step: string, line: string) => Promise<void>;
35	
36	type MigrationRow = {
37	  id: string;
38	  sourceHost: string;
39	  sourcePort: number;
40	  sourceUser: string;
41	  sourcePasswordEnc: string | null;
42	};
43	
44	type TargetServer = {
45	  id: string;
46	  rootPassword: string | null;
47	  rootPasswordEnc?: string | null;
48	  sshPort: number | null;
49	  dedicatedIp?: { address: string } | null;
50	};
51	
52	type DbItem = { engine: string; name: string; user: string; passEnc?: string };
53	type Items = { paths?: string[]; databases?: DbItem[] };
54	
55	export type RealMigrationInput = {
56	  migration: MigrationRow;
57	  target: TargetServer | null;
58	  items: Items;
59	  report: ReportFn;
60	};
61	
62	// ---- Timeouts -------------------------------------------------------------
63	const CONNECT_TIMEOUT_MS = 20_000;
64	const SETUP_TIMEOUT_MS = 60_000; // installs, mkdir, small writes
65	const TRANSFER_TIMEOUT_MS = Number(process.env.MIGRATE_EXEC_TIMEOUT_MS ?? 45 * 60_000); // rsync/dump
66	
67	// ---- Strict allowlist validators (throw on any violation) -----------------
68	// Charsets below are deliberately shell-inert: no quotes, spaces, metachars, or
69	// newlines. Validated values are therefore safe to interpolate into a command.
70	const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
71	const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
72	const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
73	const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
74	const IDENT_RE = /^[A-Za-z0-9_]{1,64}$/; // DB name / DB user
75	const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/; // absolute path, safe charset
76	
77	function assert(cond: unknown, msg: string): asserts cond {
78	  if (!cond) throw new Error(msg);
79	}
80	
81	function validHost(h: string): boolean {
82	  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
83	}
84	
85	function validPath(p: string): boolean {
86	  return typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
87	}
88	
89	/** dirname of a validated absolute path (both inputs/outputs are shell-inert). */
90	function parentDir(p: string): string {
91	  const i = p.lastIndexOf("/");
92	  return i <= 0 ? "/" : p.slice(0, i);
93	}
