187	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
188	      `/dashboard/servers/${server.id}`
189	    );
190	    return;
191	  }
192	
193	  const { conn, row: nodeRow } = await nodeFor(server);
194	  const storage = server.plan.storageTier === "hdd"
195	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
196	    : nodeRow?.storageNvme ?? "vmdata";
197	
198	  const vmid = server.vmid ?? (await conn.nextVmid());
199	  const password = generatePassword();
200	
201	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
202	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
203	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
204	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
205	  const { getSettingBool: _settingBool } = await import("../lib/settings");
206	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
207	  if (wantDedicated && ovhConfigured()) {
208	    try {
209	      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
210	      // server's already-ASSIGNED IP rather than claiming a second pool IP.
211	      dedicated = await allocateDedicatedIp(server.id, vmid);
212	    } catch (e) {
213	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
214	    }
215	  }
216	  // Node-aware + transactionally-claimed allocation (passing the server id enables
217	  // the claim path, so two concurrent provisions can't pick the same IP/port).
218	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
219	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
220	
221	  await db.server.update({
222	    where: { id: server.id },
223	    data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
224	  });
225	
226	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
227	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
228	  // (worker restart mid-clone, or any transient failure in the steps below) would
229	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
230	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
231	  // the clone is idempotent, so skip it when the VM is already present.
232	  let vmAlreadyExists = false;
233	  try {
234	    await conn.vmStatus(vmid);
235	    vmAlreadyExists = true;
236	  } catch {
237	    vmAlreadyExists = false;
238	  }
239	  if (vmAlreadyExists) {
240	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
241	  } else {
242	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
243	      newid: vmid,
244	      name: server.hostname,
245	      full: 1,
246	      storage,
247	    });
248	    await conn.waitForTask(cloneUpid, 600_000);
249	  }
250	
251	  // Per-server cloud-init snippet (base + panel/app install + add-ons)
252	  const snippet = buildCloudInit(server);
253	  await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8").catch((e) =>
254	    console.error("[worker] snippet write failed", e)
255	  );
256	
257	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
258	  const sshkeys = keys.length
259	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
260	    : undefined;
261	  const cfg: Record<string, any> = {
262	    cores: server.plan.cpuCores,
263	    memory: server.plan.ramMB,
264	    ciuser: "root",
265	    cipassword: password,
266	    sshkeys,
267	    nameserver: "1.1.1.1 8.8.8.8",
268	    onboot: 1,
269	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
270	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
271	  };
272	  if (dedicated) {
273	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
274	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
275	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
276	  } else {
277	    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
278	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
279	  }
280	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
281	
282	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
283	    disk: "scsi0",
284	    size: `${server.plan.diskGB}G`,
285	  });
286	
287	  if (!SANDBOX && !dedicated) await syncPortForwards();
288	
289	  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
290	  await conn.waitForTask(startUpid);
291	
292	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
293	  const isImage = server.osTemplate.category !== "PLAIN_OS";
294	  const sshLine = dedicated
295	    ? `ssh root@${dedicated.address}`
296	    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
297	  await notify(
298	    server.userId,
299	    `Server ${server.hostname} is ready`,
300	    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
301	    `/dashboard/servers/${server.id}`
302	  );
303	}
