396	async function suspend(job: Job, unsuspend: boolean) {
397	  const server = await loadServer(job);
398	  if (SANDBOX) {
399	    if (unsuspend) {
400	      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null } });
401	    } else {
402	      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
403	    }
404	    return;
405	  }
406	  const { conn, row: nodeRow } = await nodeFor(server);
407	  if (unsuspend) {
408	    // The dedicated IP was returned to the pool while suspended — re-allocate one
409	    // and reconfigure the public network before starting the VM back up.
410	    if (server.vmid) {
411	      const { getSettingBool: _sb } = await import("../lib/settings");
412	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
413	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
414	      let reconfigured = alreadyHas ? true : false;
415	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
416	        try {
417	          const d = await allocateDedicatedIp(server.id, server.vmid);
418	          if (d) {
419	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
420	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
421	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
422	            });
423	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
424	            reconfigured = true;
425	          }
426	        } catch (e) {
427	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
428	        }
429	      }
430	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
431	      // the Virtual MAC + failover IP that suspend released back to the pool — that
432	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
433	      // with a valid, non-conflicting network instead of a dead public config.
434	      if (!reconfigured) {
435	        try {
436	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
437	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
438	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
439	            net0: `virtio,bridge=${nodeRow?.bridge ?? "vmbr1"}`,
440	            ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`,
441	          });
442	          await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort } });
443	        } catch (e) {
444	          console.error("[worker] NAT fallback on unsuspend failed", e);
445	        }
446	      }
447	    }
448	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null } });
449	    if (!SANDBOX) await syncPortForwards();
450	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
451	    await conn.waitForTask(upid);
452	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
453	  } else {
454	    try {
455	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
456	      await conn.waitForTask(upid);
457	    } catch { /* may already be stopped */ }
458	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
459	    if (!SANDBOX) await syncPortForwards();
460	    // Return the dedicated IP to the pool while the server is suspended, so it
461	    // can be handed to a paying server. Re-allocated on unsuspend.
462	    if (ovhConfigured()) {
463	      try {
464	        const had = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
465	        if (had) {
466	          await releaseDedicatedIp(server.id);
467	          // MUST also clear the address off the server: `Server.ipAddress` is UNIQUE,
468	          // so leaving the released IP here makes the next server that claims it fail
469	          // with P2002 — that server then silently lands on NAT while its OVH Virtual
470	          // MAC stays allocated and billable. (NAT servers keep their private IP.)
471	          await db.server.update({
472	            where: { id: server.id },
473	            data: { ipAddress: null, ipv6: null },
474	          });
475	        }
476	      } catch (e) {
477	        console.error("[worker] release dedicated IP on suspend failed", e);
478	      }
479	    }
480	  }
481	}
