491	async function resize(job: Job) {
492	  const server = await loadServer(job);
493	  const payload = (job.payload ?? {}) as { planId?: string };
494	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
495	  if (!newPlan) throw new Error("resize: target plan not found");
496	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
497	
498	  if (SANDBOX) {
499	    await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
500	    await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
501	      `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${newPlan.diskGB} GB disk`,
502	      `/dashboard/servers/${server.id}`);
503	    return;
504	  }
505	
506	  const { conn } = await nodeFor(server);
507	  const wasRunning = server.status === "RUNNING";
508	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
509	    cores: newPlan.cpuCores,
510	    memory: newPlan.ramMB,
511	  });
512	  if (newPlan.diskGB > server.plan.diskGB) {
513	    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
514	      disk: "scsi0",
515	      size: `${newPlan.diskGB}G`,
516	    });
517	  }
518	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
519	  // CPU/RAM changes need a power cycle to apply
520	  if (wasRunning) {
521	    try {
522	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
523	      await conn.waitForTask(stopUpid, 120_000);
524	    } catch {
525	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
526	      await conn.waitForTask(stopUpid);
527	    }
528	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
529	    await conn.waitForTask(startUpid);
530	  }
531	  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
532	    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${newPlan.diskGB} GB disk`,
533	    `/dashboard/servers/${server.id}`);
534	}
