536	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
537	  const server = await loadServer(job);
538	  const payload = (job.payload ?? {}) as { name?: string };
539	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
540	  if (!name) throw new Error("snapshot: invalid name");
541	  if (SANDBOX) {
542	    await notify(
543	      server.userId,
544	      `Snapshot ${op} (sandbox): ${name}`,
545	      `Sandbox snapshot ${op} completed (no real VM was touched).`,
546	      `/dashboard/servers/${server.id}`
547	    );
548	    return;
549	  }
550	  const { conn } = await nodeFor(server);
551	  let upid: string;
552	  if (op === "create") {
553	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
554	  } else if (op === "delete") {
555	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
556	  } else {
557	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
558	  }
559	  await conn.waitForTask(upid, 600_000);
560	  if (op === "rollback") {
561	    // rollback leaves the VM stopped; bring it back if the server should be running
562	    const current = await db.server.findUnique({ where: { id: server.id } });
563	    if (current?.status === "RUNNING") {
564	      try {
565	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
566	        await conn.waitForTask(startUpid);
567	      } catch { /* may already be running */ }
568	    }
569	  }
570	}
