572	async function passwordReset(job: Job) {
573	  const server = await loadServer(job);
574	  if (SANDBOX) {
575	    // Sandbox: rotate the stored password only — never touch a real VM.
576	    const password = generatePassword();
577	    await db.server.update({ where: { id: server.id }, data: { rootPassword: null, rootPasswordEnc: encryptSecret(password) } });
578	    await notify(
579	      server.userId,
580	      `Root password reset (sandbox) for ${server.hostname}`,
581	      "Your new root password is on the server's Overview tab (no real VM was touched).",
582	      `/dashboard/servers/${server.id}`
583	    );
584	    return;
585	  }
586	  if (!server.vmid) throw new Error("password reset: server has no VM yet");
587	  const { conn } = await nodeFor(server);
588	  const password = generatePassword();
589	
590	  // Preferred path: set it live via the qemu-guest-agent (no reboot needed).
591	  let applied = false;
592	  try {
593	    const upid = await conn.post(
594	      `/nodes/${conn.node}/qemu/${server.vmid}/agent/set-user-password`,
595	      { username: "root", password }
596	    );
597	    if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);
598	    applied = true;
599	  } catch (e) {
600	    console.error("[worker] agent set-user-password failed, falling back to cloud-init", e);
601	  }
602	
603	  // Fallback: rewrite cloud-init password and reboot so it reapplies.
604	  if (!applied) {
605	    await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { cipassword: password });
606	    if (server.status === "RUNNING") {
607	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/reboot`, {});
608	      await conn.waitForTask(upid);
609	    }
610	  }
611	
612	  await db.server.update({ where: { id: server.id }, data: { rootPassword: null, rootPasswordEnc: encryptSecret(password) } });
613	  await notify(
614	    server.userId,
615	    `Root password reset for ${server.hostname}`,
616	    "Your new root password is available on the server's Overview tab.",
617	    `/dashboard/servers/${server.id}`
618	  );
619	}
