727	async function runJob(job: Job) {
728	  // The job is already atomically claimed (status RUNNING, attempts incremented)
729	  // by the loop's compare-and-swap before we get here — see the CAS in main().
730	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
731	  try {
732	    await handlers[job.type](job);
733	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
734	    console.log(`[worker] job ${job.id} DONE`);
735	  } catch (e: any) {
736	    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
737	    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
738	    // leak the server's root password into the thrown message. Redact it before
739	    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
740	    // sever the match. Best-effort — never let redaction lookup fail the job path.
741	    if (job.serverId) {
742	      try {
743	        const s = await db.server.findUnique({
744	          where: { id: job.serverId },
745	          select: { rootPassword: true, rootPasswordEnc: true },
746	        });
747	        const pw = s ? serverRootPassword(s) : null;
748	        if (pw) error = error.split(pw).join("***");
749	      } catch {
750	        /* best-effort redaction */
751	      }
752	    }
753	    error = error.slice(0, 2000);
754	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
755	    const current = await db.job.findUnique({ where: { id: job.id } });
756	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
757	    await db.job.update({
758	      where: { id: job.id },
759	      data: { status: retriable ? "QUEUED" : "FAILED", error },
760	    });
761	    if (!retriable) {
762	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
763	      if (job.serverId) {
764	        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
765	        if (stillExists) {
766	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
767	          // A terminally-failed PROVISION must not leak its allocated dedicated IP:
768	          // release it back to the pool (deletes the billable OVH Virtual MAC) and
769	          // clear the (UNIQUE) ipAddress so the next server can claim it.
770	          if (job.type === "PROVISION" && !SANDBOX) {
771	            await releaseDedicatedIp(job.serverId).catch((err) =>
772	              console.error(`[worker] release dedicated IP on failed provision ${job.id}`, err)
773	            );
774	            await db.server
775	              .update({ where: { id: job.serverId }, data: { ipAddress: null } })
776	              .catch(() => {});
777	          }
778	        }
779	      }
780	    }
781	  }
782	}
783	
784	/**
785	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
786	 * killed worker leaves a job RUNNING forever, which permanently blocks the
787	 * server's "one in-flight job" guard and strands it in a transitional state.
788	 */
789	async function reapStuckJobs() {
790	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
791	  for (const job of stuck) {
792	    const retriable = job.attempts < MAX_ATTEMPTS;
793	    await db.job.update({
794	      where: { id: job.id },
795	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
796	    });
797	    if (!retriable) {
798	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
799	      if (job.serverId) {
800	        const s = await db.server.findUnique({ where: { id: job.serverId } });
801	        if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
802	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
803	        }
804	      }
805	    }
806	    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
807	  }
808	}
