810	async function main() {
811	  console.log("[worker] Nxeon provisioning worker starting");
812	  await reapStuckJobs();
813	  if (!SANDBOX) await syncPortForwards();
814	  console.log("[worker] port forwards synced");
815	
816	  let lastSweep = 0;
817	  let lastIpSync = 0;
818	  let lastGameSweep = 0;
819	  let lastGeoSweep = 0;
820	  let lastMonitorSweep = 0;
821	  let lastBackupSweep = 0;
822	  for (;;) {
823	    if (Date.now() - lastSweep > 10 * 60_000) {
824	      lastSweep = Date.now();
825	      try {
826	        await billingSweep();
827	      } catch (e) {
828	        console.error("[billing] sweep error", e);
829	      }
830	      // Renewals for the add-on products (business email, block-storage volumes).
831	      try {
832	        await productRenewalSweep();
833	      } catch (e) {
834	        console.error("[product-billing] sweep error", e);
835	      }
836	    }
837	    // Auto-update opted-in game servers every ~6h
838	    if (Date.now() - lastGameSweep > 6 * 60 * 60_000) {
839	      lastGameSweep = Date.now();
840	      try {
841	        await gameUpdateSweep();
842	      } catch (e) {
843	        console.error("[game-update] sweep error", e);
844	      }
845	    }
846	    // Geo-enrich recent visits (~90s) and run monitoring alerts (~10 min)
847	    if (Date.now() - lastGeoSweep > 90_000) {
848	      lastGeoSweep = Date.now();
849	      try {
850	        await geoEnrichSweep();
851	      } catch (e) {
852	        console.error("[geo] sweep error", e);
853	      }
854	    }
855	    if (Date.now() - lastBackupSweep > 15 * 60_000) {
856	      lastBackupSweep = Date.now();
857	      try {
858	        await scheduledBackupSweep();
859	      } catch (e) {
860	        console.error("[backup-schedule] sweep error", e);
861	      }
862	    }
863	    if (Date.now() - lastMonitorSweep > 10 * 60_000) {
864	      lastMonitorSweep = Date.now();
865	      try {
866	        await monitorSweep();
867	      } catch (e) {
868	        console.error("[monitor] sweep error", e);
869	      }
870	      try {
871	        await abuseSweep();
872	      } catch (e) {
873	        console.error("[abuse] sweep error", e);
874	      }
875	    }
876	    // Pull newly-delivered OVH IPs into the pool every 5 min
877	    if (ovhConfigured() && Date.now() - lastIpSync > 5 * 60_000) {
878	      lastIpSync = Date.now();
879	      try {
880	        const r = await syncDedicatedIpPool();
881	        if (r.imported > 0) console.log(`[worker] dedicated IP pool: imported ${r.imported}, total ${r.total}`);
882	        // Low-pool alert, gated by the Settings toggle. (Auto-ordering IPs spends
883	        // real money via OVH and is intentionally left as a manual admin action.)
884	        const { getSettingBool, getSettingInt } = await import("../lib/settings");
885	        if (await getSettingBool("dedicated_ip_autoreplenish", false)) {
886	          const free = await db.dedicatedIp.count({ where: { status: "FREE" } });
887	          const threshold = await getSettingInt("dedicated_ip_replenish_threshold", 2);
888	          if (free < threshold) {
889	            const recent = await db.notification.findFirst({
890	              where: { title: { contains: "Dedicated IP pool low" }, createdAt: { gt: new Date(Date.now() - 6 * 3600_000) } },
891	            });
892	            if (!recent) {
893	              const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
894	              await db.notification.createMany({
895	                data: admins.map((a) => ({
896	                  userId: a.id,
897	                  title: `Dedicated IP pool low (${free} free)`,
898	                  body: `Free dedicated IPs (${free}) fell below the replenish threshold (${threshold}). Order more failover IPs from OVH, then the pool auto-imports on the next sync.`,
899	                  href: "/admin/ips",
900	                })),
901	              });
902	            }
903	          }
904	        }
905	      } catch (e) {
906	        console.error("[worker] IP pool sync error", e);
907	      }
908	    }
909	    try {
910	      const candidate = await db.job.findFirst({
911	        where: { status: "QUEUED" },
912	        orderBy: { createdAt: "asc" },
913	      });
914	      if (candidate) {
915	        // Atomic claim: only the worker whose updateMany matches the still-QUEUED
916	        // row wins. If count===0 another worker (or a retry) already took it, so we
917	        // skip and re-poll — prevents the same job running twice under concurrency.
918	        const claim = await db.job.updateMany({
919	          where: { id: candidate.id, status: "QUEUED" },
920	          data: { status: "RUNNING", attempts: { increment: 1 } },
921	        });
922	        if (claim.count === 1) {
923	          const claimed = await db.job.findUnique({ where: { id: candidate.id } });
924	          if (claimed) await runJob(claimed);
925	        }
926	        // else: lost the race — loop immediately to grab the next queued job.
927	      } else {
928	        await new Promise((r) => setTimeout(r, POLL_MS));
929	      }
930	    } catch (e) {
931	      console.error("[worker] loop error", e);
932	      await new Promise((r) => setTimeout(r, POLL_MS));
933	    }
934	  }
935	}
936	
937	main();
