47	// ----------------------------------------------------------------------------
48	// Real issuance path (SSH + certbot). Only reachable when
49	// `!SANDBOX && ENABLE_REAL_SSL === "1"` — see the guard in sslIssue().
50	// ----------------------------------------------------------------------------
51	
52	type SshResult = { code: number | null; stdout: string; stderr: string };
53	
54	/**
55	 * Single-quote a value for safe interpolation into a POSIX shell command.
56	 * We already restrict the domain to a strict charset below, but everything that
57	 * reaches a remote shell is quoted defensively regardless.
58	 */
59	function shellQuote(s: string): string {
60	  return `'${s.replace(/'/g, `'\\''`)}'`;
61	}
62	
63	/** Domains must look like real hostnames before we hand them to certbot. */
64	function assertSafeDomain(domain: string): void {
65	  if (!/^(?=.{1,253}$)([a-zA-Z0-9-]{1,63}\.)+[a-zA-Z]{2,63}$/.test(domain)) {
66	    throw new Error(`Refusing to issue for an unexpected domain: ${domain}`);
67	  }
68	}
