import { db } from "../lib/db";
import { pve, node as envNode, waitForTask, nextVmid, pveFor, vmStatus } from "../lib/proxmox";
import { SANDBOX } from "../lib/sandbox";
import type { Job } from "@prisma/client";

/**
 * Block storage volume handlers (add-on disks attached to a VPS).
 *
 * `worker/index.ts` owns the job loop and the `handlers` map; wire these in there:
 *   VOLUME_CREATE: volumeCreate,
 *   VOLUME_ATTACH: volumeAttach,
 *   VOLUME_DETACH: volumeDetach,
 *   VOLUME_DELETE: volumeDelete,
 *
 * Ownership + validation are enforced at enqueue time (lib/actions-volumes.ts),
 * so these handlers trust `payload.volumeId`.
 *
 * A volume's underlying Proxmox disk only exists once it has been attached at
 * least once. `Volume.diskName` stores the STABLE Proxmox volume id of that disk
 * (e.g. "vmdata:vm-101-disk-1") — not a slot — because the slot/unused index
 * changes across detach/re-attach; we always re-scan the VM config to find the
 * disk's current key (scsiN while attached, unusedN while detached).
 */

async function loadVolume(job: Job) {
  const payload = (job.payload ?? {}) as { volumeId?: string };
  if (!payload.volumeId) throw new Error("volume job: missing volumeId");
  const volume = await db.volume.findUnique({
    where: { id: payload.volumeId },
    include: { server: { include: { node: true } } },
  });
  if (!volume) throw new Error(`Volume ${payload.volumeId} not found`);
  return volume;
}

/** Resolve the Proxmox client + node row for a server (mirrors worker/index.ts). */
async function nodeFor(server: any) {
  const n =
    server?.node ??
    (await db.node.findFirst({ where: { isPrimary: true } })) ??
    (await db.node.findFirst({ where: { enabled: true } }));
  if (!n) {
    return {
      conn: {
        get: pve.get,
        post: pve.post,
        put: pve.put,
        del: pve.del,
        node: envNode,
        waitForTask,
        nextVmid,
        vmStatus,
      } as any,
      row: null,
    };
  }
  return {
    conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }),
    row: n,
  };
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[volumes] notify failed", e);
  }
}

/** Strip Proxmox disk options: "vmdata:vm-101-disk-1,size=10G" -> "vmdata:vm-101-disk-1". */
function volidOf(configValue: unknown): string {
  return String(configValue ?? "").split(",")[0].trim();
}

/** First free scsiN slot (scsi0 is the OS disk). Proxmox supports scsi0..scsi30. */
function freeScsiSlot(config: Record<string, any>): string {
  for (let i = 1; i <= 30; i++) {
    if (config[`scsi${i}`] === undefined) return `scsi${i}`;
  }

