// ============================================================================
// Control panel (cPanel/Plesk-style VPS management over SSH)
// ----------------------------------------------------------------------------
// Every row is scoped to a Server + owning userId. Side-effecting work (writing
// nginx vhosts, creating DBs, installing apps, editing crontab, service control)
// runs in the worker over SSH (worker/websites|databases|apps|services.ts),
// gated by SANDBOX exactly like the rest of the platform. Quick reads (lists,
// service status, process snapshot) are served straight from these tables /
// synthetic sandbox data. `serverId` uses a cascade so a server teardown cleans
// up its panel rows.
// ============================================================================

/// A website (nginx server block + docroot under /var/www) the customer added
/// to their VPS, optionally with a chosen PHP-FPM version and Let's Encrypt SSL.
model Website {
  id           String   @id @default(cuid())
  userId       String
  serverId     String
  server       Server   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  domain       String
  docRoot      String   // absolute path under /var/www/<domain>
  phpVersion   String?  // e.g. "8.3", or null for a static site
  ssl          Boolean  @default(false)
  enabled      Boolean  @default(true)
  isSubdomain  Boolean  @default(false)
  parentDomain String?  // the base site this is a subdomain of (display only)
  appSlug      String?  // set when provisioned by the one-click app installer
  status       String   @default("PENDING") // PENDING | ACTIVE | DISABLED | FAILED | DELETING
  error        String?
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt

  @@unique([serverId, domain])
  @@index([userId])
  @@index([serverId])
}

/// A MySQL/MariaDB or PostgreSQL database (+ its owner DB user) created on the
/// customer's VPS. The generated password is shown ONCE at creation; `passwordEnc`
/// only holds it transiently so the worker can apply it, then it is cleared.
model VpsDatabase {
  id          String   @id @default(cuid())
  userId      String
  serverId    String
  server      Server   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  engine      String   // "mysql" | "postgres"
  name        String
  dbUser      String
  passwordEnc String?  // encrypted; CLEARED once the create job applies it
  status      String   @default("PENDING") // PENDING | ACTIVE | FAILED | DELETING
  error       String?
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@unique([serverId, engine, name])
  @@index([userId])
  @@index([serverId])
}

/// A one-click application install (WordPress, Ghost, Nextcloud, …). Reuses the
/// Website + VpsDatabase primitives; admin credentials are shown once via the
/// returned row / notification. `adminPassEnc` is cleared after the install job.
model AppInstall {
  id           String   @id @default(cuid())
  userId       String
  serverId     String
  server       Server   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  appSlug      String   // wordpress | ghost | nextcloud | ...
  domain       String
  websiteId    String?  // the Website row provisioned for it
  databaseId   String?  // the VpsDatabase row provisioned for it
  url          String?  // final site URL
  adminUser    String?
  adminPassEnc String?  // encrypted admin password; CLEARED after install
  status       String   @default("PENDING") // PENDING | INSTALLING | ACTIVE | FAILED
  error        String?
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt

  @@index([userId])
  @@index([serverId])
}

/// A crontab entry managed for the customer's VPS. All enabled entries for a
/// server are rendered into a single Nxeon-owned crontab block on CRON_SYNC.
model CronJob {
  id         String   @id @default(cuid())
  userId     String
  serverId   String
  server     Server   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  schedule   String   // 5-field cron expression
  command    String
  comment    String?
  enabled    Boolean  @default(true)
  status     String   @default("PENDING") // PENDING | ACTIVE | FAILED | DELETING
  error      String?
  createdAt  DateTime @default(now())
  updatedAt  DateTime @updatedAt

  @@index([userId])
  @@index([serverId])
}

