/**
 * Shared, DEPENDENCY-FREE constants + types for the customer control panel.
 *
 * This module imports NOTHING (no node builtins, no ssh2, no Prisma) so it is
 * safe to import from BOTH client components (the cPanel UI) and server code
 * (actions + worker). Anything that touches SSH/secrets lives in lib/ssh-exec.ts
 * (server/worker only). Server-action files may only export async functions, so
 * every shared const/type the panel needs is parked here.
 */

// ---- PHP ------------------------------------------------------------------

/** PHP-FPM versions the panel can install/select. "" means a static site. */
export const PHP_VERSIONS = ["8.3", "8.2", "8.1", "7.4"] as const;
export type PhpVersion = (typeof PHP_VERSIONS)[number];

// ---- Databases ------------------------------------------------------------

export const DB_ENGINES = ["mysql", "postgres"] as const;
export type DbEngine = (typeof DB_ENGINES)[number];

export const DB_ENGINE_LABEL: Record<DbEngine, string> = {
  mysql: "MySQL / MariaDB",
  postgres: "PostgreSQL",
};

// ---- One-click apps -------------------------------------------------------

export type AppCatalogItem = {
  slug: string;
  name: string;
  description: string;
  /** Engine the app needs provisioned, or null for none. */
  engine: DbEngine | null;
  /** PHP version the app runs on, or null for a non-PHP app (e.g. Ghost). */
  php: PhpVersion | null;
  emoji: string;
};

/** The one-click app catalog. Each reuses the Website + Database primitives. */
export const APP_CATALOG: AppCatalogItem[] = [
  {
    slug: "wordpress",
    name: "WordPress",
    description: "The world's most popular CMS — blogs, business sites, shops.",
    engine: "mysql",
    php: "8.3",
    emoji: "📝",
  },
  {
    slug: "ghost",
    name: "Ghost",
    description: "Modern publishing & newsletters (Node.js).",
    engine: "mysql",
    php: null,
    emoji: "👻",
  },
  {
    slug: "nextcloud",
    name: "Nextcloud",
    description: "Self-hosted files, calendar & contacts — your own cloud.",
    engine: "mysql",
    php: "8.3",
    emoji: "☁️",
  },
  {
    slug: "joomla",
    name: "Joomla",
    description: "Flexible open-source CMS for portals & communities.",
    engine: "mysql",
    php: "8.2",
    emoji: "🧩",
  },
  {
    slug: "matomo",
    name: "Matomo",
    description: "Privacy-first, self-hosted web analytics.",
    engine: "mysql",
    php: "8.2",
    emoji: "📊",
  },
];

export function appBySlug(slug: string): AppCatalogItem | undefined {
  return APP_CATALOG.find((a) => a.slug === slug);
}

// ---- Services -------------------------------------------------------------

export type ServiceDef = { unit: string; label: string };

/** Common services the panel can start/stop/restart + show status for. */
export const COMMON_SERVICES: ServiceDef[] = [
  { unit: "nginx", label: "Nginx (web server)" },
  { unit: "mysql", label: "MySQL / MariaDB" },
  { unit: "postgresql", label: "PostgreSQL" },
  { unit: "php-fpm", label: "PHP-FPM" },
  { unit: "docker", label: "Docker" },
  { unit: "redis-server", label: "Redis" },
  { unit: "ssh", label: "SSH (sshd)" },
];

export const SERVICE_ACTIONS = ["start", "stop", "restart"] as const;
export type ServiceActionKind = (typeof SERVICE_ACTIONS)[number];

// ---- Cron -----------------------------------------------------------------

/** Human-friendly cron schedule presets for the picker. */
export const CRON_PRESETS: { label: string; value: string }[] = [
  { label: "Every minute", value: "* * * * *" },
  { label: "Every 5 minutes", value: "*/5 * * * *" },
  { label: "Every 15 minutes", value: "*/15 * * * *" },
  { label: "Hourly", value: "0 * * * *" },
  { label: "Daily at midnight", value: "0 0 * * *" },
  { label: "Daily at 3am", value: "0 3 * * *" },
  { label: "Weekly (Sun 00:00)", value: "0 0 * * 0" },
  { label: "Monthly (1st 00:00)", value: "0 0 1 * *" },
];

// ---- Shared row shapes returned to the client -----------------------------

export type WebsiteRow = {
  id: string;
  domain: string;
  docRoot: string;
  phpVersion: string | null;
  ssl: boolean;
  enabled: boolean;
  isSubdomain: boolean;
  parentDomain: string | null;
  appSlug: string | null;
  status: string;
  error: string | null;
  createdAt: string;
};

export type DatabaseRow = {
  id: string;
  engine: string;
  name: string;
  dbUser: string;
  status: string;
  error: string | null;
  createdAt: string;
};

export type AppRow = {
  id: string;
  appSlug: string;
  domain: string;
  url: string | null;
  adminUser: string | null;
  status: string;
  error: string | null;
  createdAt: string;
};

export type CronRow = {
  id: string;
  schedule: string;
  command: string;
  comment: string | null;
  enabled: boolean;
  status: string;
  error: string | null;
  createdAt: string;
};

export type ServiceStatus = {
  unit: string;
  label: string;
  state: "running" | "stopped" | "not-installed" | "unknown";
};

export type ProcessSnapshot = {
  cpuPct: number; // overall CPU %
  memUsedMB: number;
  memTotalMB: number;
  diskUsedGB: number;
  diskTotalGB: number;
  loadAvg: [number, number, number];
  uptimeSec: number;
  top: { pid: number; user: string; cpu: number; mem: number; command: string }[];
};

/**
 * Shared, injection-safe SSH execution foundation for the customer control
 * panel (websites, databases, one-click apps, cron & services).
 *
 * This is a plain server-side module (NO "use server", no client imports) so it
 * can be used by both the inline read helpers (lib/cpanel-inline.ts) and the
 * worker executors (worker/websites|databases|apps|services.ts). It NEVER runs
 * in the browser — the customer's root credentials stay on the server.
 *
 * It mirrors the hardening in worker/migrate-real.ts on two axes:
 *
 *   1. STRICT ALLOWLIST VALIDATION. Every non-secret value that will be
 *      interpolated into a remote command MUST match a shell-inert allowlist
 *      (regexes below contain no quotes/spaces/metacharacters/newlines) or the
 *      operation FAILS. We reject — never sanitize. Callers validate up front
 *      with the `assert*` helpers so a bad value can never reach a shell.
 *
 *   2. SECRETS NEVER TOUCH A COMMAND STRING. Generated DB / app passwords are
 *      written to the far side via a command's STDIN (`execInput`) or an SFTP
 *      file — never as an argv token. Command strings reference only file paths
 *      or values that passed the allowlist.
 *
 * Connection target + root password derivation is identical to lib/sftp.ts and
 * worker/ssl.ts (dedicated IP → own IP:22, else PUBLIC_IP:sshPort; user root).
 */
import { Client, type ClientChannel } from "ssh2";
import { connectionTarget, serverRootPassword, type SftpServer } from "./sftp";

// ---- Timeouts -------------------------------------------------------------
export const SSH_CONNECT_TIMEOUT_MS = 15_000;
/** Quick inline reads (list/status/snapshot) — kept short so a slow box can't
 *  wedge a page render. */
export const QUICK_TIMEOUT_MS = 12_000;
/** Small mutating commands (write a vhost, create a DB, edit crontab). */
export const SETUP_TIMEOUT_MS = 60_000;
/** Long installs (php-fpm, an engine, an app download). */
export const INSTALL_TIMEOUT_MS = Number(process.env.CPANEL_INSTALL_TIMEOUT_MS ?? 15 * 60_000);

// ---- Strict allowlist validators (throw on any violation) -----------------
// Every charset below is deliberately shell-inert.
export const DOMAIN_RE =
  /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/;
/** DB / DB-user identifier: letters, digits, underscore. */
export const IDENT_RE = /^[A-Za-z0-9_]{1,32}$/;
/** PHP version like 8.3 / 7.4. */
export const PHP_VERSION_RE = /^\d\.\d$/;
/** systemd unit name (bare service name we control from a fixed list). */
export const SERVICE_RE = /^[a-z0-9][a-z0-9_.-]{0,63}$/;
/** Absolute path with a safe charset, no traversal / double slash. */
export const PATH_RE = /^\/[A-Za-z0-9._/-]{1,255}$/;
/** A single crontab time field: digits, * , - , / and commas only. */
export const CRON_FIELD_RE = /^[0-9*,/-]{1,64}$/;
/** App slug from our fixed catalog. */
export const SLUG_RE = /^[a-z][a-z0-9-]{0,31}$/;

export function assert(cond: unknown, msg: string): asserts cond {
  if (!cond) throw new Error(msg);
}

export function assertDomain(d: string): void {
  assert(typeof d === "string" && DOMAIN_RE.test(d), `Unsupported domain: ${d}`);
}
export function assertIdent(v: string, what: string): void {
  assert(typeof v === "string" && IDENT_RE.test(v), `Unsupported ${what}: ${v}`);
}
export function assertPhp(v: string): void {
  assert(typeof v === "string" && PHP_VERSION_RE.test(v), `Unsupported PHP version: ${v}`);
}
export function assertService(v: string): void {
  assert(typeof v === "string" && SERVICE_RE.test(v), `Unsupported service: ${v}`);
}
export function assertPath(p: string): void {
  assert(
    typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//"),
    `Unsupported path: ${p}`
  );
}
export function assertSlug(s: string): void {
  assert(typeof s === "string" && SLUG_RE.test(s), `Unsupported app: ${s}`);
}

/**
 * Validate a 5-field cron schedule. Each field must match CRON_FIELD_RE, so the
 * whole expression is shell-inert (no metacharacters). Returns the normalized
 * single-spaced expression, or throws.
 */
export function assertCronSchedule(schedule: string): string {
  assert(typeof schedule === "string", "Invalid schedule.");
  const fields = schedule.trim().split(/\s+/);
  assert(fields.length === 5, "A cron schedule must have exactly 5 fields (min hour dom mon dow).");
  for (const f of fields) assert(CRON_FIELD_RE.test(f), `Unsupported cron field: ${f}`);
  return fields.join(" ");
}

/**
 * Defensive POSIX single-quote. Even allowlisted values are quoted when they are
 * interpolated, so a value that (against expectation) slipped through has no
 * shell effect. NEVER used for secrets — those go through STDIN/SFTP.
 */
export function shellQuote(s: string): string {
  return `'${String(s).replace(/'/g, `'\\''`)}'`;
}

// ---- SSH plumbing ---------------------------------------------------------

export type SshResult = { code: number | null; stdout: string; stderr: string };

/**
 * Run one command on an already-connected client, capturing output + exit code.
 * Rejects if the command exceeds `timeoutMs` (the channel is torn down so a hung
 * remote command can't wedge the worker/page).
 */
export function exec(conn: Client, command: string, timeoutMs: number): Promise<SshResult> {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      let settled = false;
      const timer = setTimeout(() => {
        if (settled) return;
        settled = true;
        try {
          stream.close();
        } catch {
          /* best effort */
        }
        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
      }, timeoutMs);
      stream
        .on("close", (code: number | null) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve({ code, stdout, stderr });
        })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
    });
  });
}

/**
 * Run a command and stream `input` into its STDIN — used to write a secret into
 * a file on the far side (`cat > file`) without the secret ever appearing as a
 * command-line argument. Mirrors worker/migrate-real.ts execRemoteInput.
 */
export function execInput(
  conn: Client,
  command: string,
  input: string,
  timeoutMs: number
): Promise<SshResult> {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      let settled = false;
      const timer = setTimeout(() => {
        if (settled) return;
        settled = true;
        try {
          stream.close();
        } catch {
          /* best effort */
        }
        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
      }, timeoutMs);
      stream
        .on("close", (code: number | null) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve({ code, stdout, stderr });
        })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
      stream.end(input);
    });
  });
}

/**
 * Open an SSH connection to a server, run `fn`, and ALWAYS end the connection.
 * Host/port/root-password derived exactly like lib/sftp. Throws a clear error if
 * the server isn't reachable yet or has no root password on record.
 *
 * Callers MUST guard SANDBOX before reaching here — no real SSH in staging.
 */
export async function withServerSsh<T>(
  server: SftpServer,
  fn: (conn: Client) => Promise<T>
): Promise<T> {
  const target = connectionTarget(server);
  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
  const password = serverRootPassword(server);
  if (!password) throw new Error("Server has no root password on record.");

  const conn = new Client();
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(() => {
      try {
        conn.end();
      } catch {
        /* best effort */
      }
      reject(new Error(`SSH connect timed out after ${Math.round(SSH_CONNECT_TIMEOUT_MS / 1000)}s`));
    }, SSH_CONNECT_TIMEOUT_MS);
    conn
      .on("ready", () => {
        clearTimeout(timer);
        resolve();
      })
      .on("error", (e) => {
        clearTimeout(timer);
        reject(e instanceof Error ? e : new Error(String(e)));
      })
      .connect({
        host: target.host,
        port: target.port,
        username: "root",
        password,
        readyTimeout: SSH_CONNECT_TIMEOUT_MS,
      });
  });
  try {
    return await fn(conn);
  } finally {
    try {
      conn.end();
    } catch {
      /* best effort */
    }
  }
}

/**
 * Detect the package manager on the far side and return the install prefix, or
 * throw if none is supported. Fixed strings only — no user input.
 */
export async function pkgInstallPrefix(conn: Client): Promise<string> {
  const pm = await exec(
    conn,
    "if command -v apt-get >/dev/null 2>&1; then echo apt; " +
      "elif command -v dnf >/dev/null 2>&1; then echo dnf; " +
      "elif command -v yum >/dev/null 2>&1; then echo yum; else echo none; fi",
    QUICK_TIMEOUT_MS
  );
  const which = pm.stdout.trim();
  if (which === "apt") return "DEBIAN_FRONTEND=noninteractive apt-get install -y";
  if (which === "dnf") return "dnf install -y";
  if (which === "yum") return "yum install -y";
  throw new Error("No supported package manager (apt-get/dnf/yum) found on the server.");
}

/** A URL-safe generated password (no shell metacharacters, no ambiguity). */
export function generateStrongPassword(len = 20): string {
  // Imported lazily so this module stays free of a top-level node:crypto need in
  // any edge context; in practice it's always server/worker.
  const { randomBytes } = require("node:crypto") as typeof import("node:crypto");
  return randomBytes(len * 2)
    .toString("base64url")
    .replace(/[-_]/g, "")
    .slice(0, len);
}

/**
 * Inline (non-worker) quick reads for the control panel: service status and a
 * live process/resource snapshot. These are cheap, read-only SSH commands with a
 * short timeout, so they run inline from the server actions rather than via a
 * queued job (mirrors how lib/sftp.ts serves file listings inline).
 *
 * SANDBOX: on staging NO real SSH is ever opened — every read returns realistic,
 * deterministic synthetic data so the whole panel UX works end to end without a
 * live VM. Plain server module (no "use server"): imported by lib/actions-cron.ts.
 */
import { SANDBOX } from "./sandbox";
import { withServerSsh, exec, assertService, shellQuote, QUICK_TIMEOUT_MS } from "./ssh-exec";
import { COMMON_SERVICES, type ServiceStatus, type ProcessSnapshot } from "./cpanel-types";
import type { SftpServer } from "./sftp";

/** Deterministic pseudo-random in [0,1) from a string seed (sandbox realism). */
function seeded(seed: string): number {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 10000) / 10000;
}

// ---------------------------------------------------------------------------
// Service status
// ---------------------------------------------------------------------------

/**
 * Status of the common services. In sandbox, nginx/ssh look running, php-fpm/
 * mysql installed-and-running, the rest a deterministic mix. On prod we ask
 * systemd for each unit in one round-trip.
 */
export async function readServiceStatuses(server: SftpServer): Promise<ServiceStatus[]> {
  if (SANDBOX) {
    return COMMON_SERVICES.map((s) => {
      let state: ServiceStatus["state"];
      if (s.unit === "nginx" || s.unit === "ssh") state = "running";
      else if (s.unit === "php-fpm" || s.unit === "mysql") state = "running";
      else state = seeded(server.id + s.unit) > 0.5 ? "running" : "not-installed";
      return { unit: s.unit, label: s.label, state };
    });
  }

  return withServerSsh(server, async (conn) => {
    const out: ServiceStatus[] = [];
    for (const s of COMMON_SERVICES) {
      assertService(s.unit);
      const q = shellQuote(s.unit);
      // is-active prints active/inactive/failed/unknown; if the unit doesn't
      // exist at all, `systemctl list-unit-files` finds nothing → not-installed.
      const r = await exec(
        conn,
        `if systemctl list-unit-files ${q}.service >/dev/null 2>&1 || systemctl status ${q} >/dev/null 2>&1; then ` +
          `systemctl is-active ${q} 2>/dev/null || echo inactive; else echo missing; fi`,
        QUICK_TIMEOUT_MS
      );
      const v = r.stdout.trim();
      let state: ServiceStatus["state"];
      if (v === "active") state = "running";
      else if (v === "missing") state = "not-installed";
      else if (v === "inactive" || v === "failed") state = "stopped";
      else state = "unknown";
      out.push({ unit: s.unit, label: s.label, state });
    }
    return out;
  });
}

// ---------------------------------------------------------------------------
// Process / resource snapshot
// ---------------------------------------------------------------------------

const SANDBOX_COMMANDS = [
  "nginx: worker process",
  "php-fpm: pool www",
  "mysqld",
  "node /var/www/app/server.js",
  "redis-server *:6379",
  "systemd --user",
  "sshd: root@pts/0",
];

export async function readProcessSnapshot(server: SftpServer): Promise<ProcessSnapshot> {
  if (SANDBOX) {
    const base = seeded(server.id);
    const cpuPct = Math.round((15 + base * 55) * 10) / 10;
    const memTotalMB = 4096;
    const memUsedMB = Math.round(memTotalMB * (0.35 + base * 0.4));
    const diskTotalGB = 80;
    const diskUsedGB = Math.round(diskTotalGB * (0.2 + base * 0.5) * 10) / 10;
    const top = SANDBOX_COMMANDS.map((command, i) => ({
      pid: 400 + i * 137 + Math.floor(seeded(server.id + i) * 90),
      user: i % 3 === 0 ? "root" : "www-data",
      cpu: Math.round(seeded(server.id + "c" + i) * 40 * 10) / 10,
      mem: Math.round(seeded(server.id + "m" + i) * 12 * 10) / 10,
      command,
    }))
      .sort((a, b) => b.cpu - a.cpu)
      .slice(0, 6);
    return {
      cpuPct,
      memUsedMB,
      memTotalMB,
      diskUsedGB,
      diskTotalGB,
      loadAvg: [
        Math.round(base * 2 * 100) / 100,
        Math.round(base * 1.6 * 100) / 100,
        Math.round(base * 1.2 * 100) / 100,
      ],
      uptimeSec: Math.floor(3600 * 24 * (2 + base * 20)),
      top,
    };
  }

  return withServerSsh(server, async (conn) => {
    // One fixed command bundle — no user input anywhere. Emits labelled lines we
    // parse below; robust to missing tools (best-effort fields).
    const script =
      "echo '#LOAD'; cat /proc/loadavg 2>/dev/null; " +
      "echo '#UP'; cat /proc/uptime 2>/dev/null; " +
      "echo '#MEM'; free -m 2>/dev/null | awk '/^Mem:/{print $2, $3}'; " +
      "echo '#DISK'; df -BG / 2>/dev/null | awk 'NR==2{gsub(/G/,\"\"); print $2, $3}'; " +
      "echo '#CPU'; awk '/^cpu /{u=$2+$4; t=$2+$4+$5; print u, t}' /proc/stat 2>/dev/null; " +
      "echo '#TOP'; ps -eo pid,user,pcpu,pmem,comm --sort=-pcpu 2>/dev/null | head -n 8";
    const r = await exec(conn, script, QUICK_TIMEOUT_MS);
    return parseSnapshot(r.stdout);
  });
}

/** Parse the labelled snapshot output into a ProcessSnapshot (best-effort). */
function parseSnapshot(out: string): ProcessSnapshot {
  const sections: Record<string, string[]> = {};
  let cur = "";
  for (const raw of out.split("\n")) {
    const line = raw.trimEnd();
    if (line.startsWith("#")) {
      cur = line.slice(1);
      sections[cur] = [];
    } else if (cur && line.trim().length) {
      sections[cur].push(line);
    }
  }
  const num = (s: string | undefined, d = 0) => {
    const n = Number(s);
    return Number.isFinite(n) ? n : d;
  };

  const load = (sections.LOAD?.[0] ?? "").split(/\s+/);
  const loadAvg: [number, number, number] = [num(load[0]), num(load[1]), num(load[2])];
  const uptimeSec = Math.floor(num((sections.UP?.[0] ?? "").split(/\s+/)[0]));
  const mem = (sections.MEM?.[0] ?? "").split(/\s+/);
  const memTotalMB = num(mem[0], 1);
  const memUsedMB = num(mem[1]);
  const disk = (sections.DISK?.[0] ?? "").split(/\s+/);
  const diskTotalGB = num(disk[0], 1);
  const diskUsedGB = num(disk[1]);
  const cpu = (sections.CPU?.[0] ?? "").split(/\s+/);
  const cpuBusy = num(cpu[0]);
  const cpuTotal = num(cpu[1], 1);
  const cpuPct = Math.round(Math.min(100, (cpuBusy / cpuTotal) * 100) * 10) / 10;

  const top = (sections.TOP ?? [])
    .filter((l) => !/^\s*PID\b/i.test(l))
    .map((l) => {
      const p = l.trim().split(/\s+/);
      return {
        pid: num(p[0]),
        user: p[1] ?? "?",
        cpu: num(p[2]),
        mem: num(p[3]),
        command: p.slice(4).join(" ") || "?",
      };
    })
    .slice(0, 6);

  return { cpuPct, memUsedMB, memTotalMB, diskUsedGB, diskTotalGB, loadAvg, uptimeSec, top };
}

