export async function createDatabase(
  serverId: string,
  engine: string,
  nameInput: string,
  userInput: string
): Promise<CreateResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "create", 10);
    if (limited) return { ok: false, error: limited };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to create a database." };
    if (await lifecycleBusy(server.id))
      return { ok: false, error: "Another server operation is in progress — try again shortly." };

    if (!(DB_ENGINES as readonly string[]).includes(engine))
      return { ok: false, error: "Choose a supported database engine." };
    const name = String(nameInput ?? "").trim();
    const dbUser = String(userInput ?? "").trim();
    if (!IDENT_RE.test(name))
      return { ok: false, error: "Database name: 1–32 letters, digits or underscores." };
    if (!IDENT_RE.test(dbUser))
      return { ok: false, error: "User name: 1–32 letters, digits or underscores." };

    const existing = await db.vpsDatabase.findFirst({
      where: { serverId: server.id, engine, name },
    });
    if (existing) return { ok: false, error: `A ${engine} database named "${name}" already exists.` };

    const count = await db.vpsDatabase.count({ where: { serverId: server.id } });
    if (count >= 50) return { ok: false, error: "Database limit reached (50 per server)." };

    const password = generateStrongPassword(20);
    const row = await db.vpsDatabase.create({
      data: {
        userId: user.id,
        serverId: server.id,
        engine: engine as DbEngine,
        name,
        dbUser,
        passwordEnc: encryptSecret(password),
        status: "PENDING",
      },
    });
    await db.job.create({ data: { type: "DB_CREATE", serverId: server.id, payload: { databaseId: row.id } } });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.db.create", detail: `${engine}/${name} on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    // Password returned ONCE — never stored in plaintext, never re-shown.
    return { ok: true, id: row.id, name, dbUser, password };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

