 * Cron: add/edit/remove crontab entries (rendered into one Nxeon-managed block
 * on the VPS by worker/services.ts on CRON_SYNC).
 * Services: start/stop/restart nginx/php-fpm/mysql/docker/… (worker SERVICE_ACTION),
 * plus inline reads for service status and a live process/resource snapshot
 * (lib/cpanel-inline.ts — sandbox-synthetic on staging, short-timeout SSH on prod).
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { assertCronSchedule } from "./ssh-exec";
import { readServiceStatuses, readProcessSnapshot } from "./cpanel-inline";
import {
  COMMON_SERVICES,
  SERVICE_ACTIONS,
  type CronRow,
  type ServiceStatus,
  type ProcessSnapshot,
} from "./cpanel-types";
import type { SftpServer } from "./sftp";

type Result = { ok: true } | { ok: false; error: string };
type CreateResult = { ok: true; id: string } | { ok: false; error: string };

const EXCLUSIVE_JOBS = [
  "PROVISION",
  "REINSTALL",
  "DELETE",
  "RESIZE",
  "SUSPEND",
  "UNSUSPEND",
  "SNAPSHOT_ROLLBACK",
  "BACKUP_RESTORE",
] as const;

/** Max length for a cron command line. */
const MAX_CMD_LEN = 500;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      userId: true,
      status: true,
      hostname: true,
      rootPassword: true,
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
