function throttle(userId: string, op: string, max: number): string | null {
  const rl = checkRateLimit(`cpanel:cron:${op}:${userId}`, { max, windowMs: 60_000 });
  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
}

async function lifecycleBusy(serverId: string): Promise<boolean> {
  const n = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
  });
  return n > 0;
}

function safeError(err: unknown): string {
  const msg = err instanceof Error ? err.message : String(err);
  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
  if (/timed out|reachable|root password|package manager/i.test(msg)) return msg.slice(0, 200);
  if (/^Unsupported |cron/i.test(msg)) return msg.slice(0, 200);
  return "Could not reach the server. Please try again shortly.";
}

/**
 * Validate a cron command: length-bounded, no NUL / newline / control chars, no
 * comment-injection into the crontab block. The command is written to the far
 * side via a here-doc body (STDIN), never interpolated into a shell command, so
 * shell metacharacters inside it run in the user's OWN crontab as intended — but
 * we still forbid newlines (would forge extra crontab lines).
 */
function validateCommand(cmd: string): string {
  const c = String(cmd ?? "");
  if (c.trim().length === 0) throw new Error("A command is required.");
  if (c.length > MAX_CMD_LEN) throw new Error(`Command is too long (max ${MAX_CMD_LEN} chars).`);
  if (/[\x00-\x08\x0a-\x1f\x7f]/.test(c)) throw new Error("Command contains invalid control characters.");
  return c.trim();
}

function rowOut(c: {
  id: string;
  schedule: string;
  command: string;
  comment: string | null;
  enabled: boolean;
  status: string;
  error: string | null;
  createdAt: Date;
}): CronRow {
  return {
    id: c.id,
    schedule: c.schedule,
    command: c.command,
    comment: c.comment,
    enabled: c.enabled,
    status: c.status,
    error: c.error,
    createdAt: c.createdAt.toISOString(),
  };
}

