"use server";

/**
 * Control panel — One-click apps.
 *
 * Install WordPress / Ghost / Nextcloud / … onto the server: provision a site
 * (vhost + docroot) + a database + the app, then report the URL / admin creds.
 * This reuses the Website + VpsDatabase primitives — installApp creates all
 * three rows (AppInstall, Website, VpsDatabase) and enqueues one APP_INSTALL
 * job; worker/apps.ts drives the whole install over SSH (sandbox-simulated on
 * staging). Admin + DB passwords are shown once (returned here / on the row).
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { encryptSecret } from "./crypto-box";
import { DOMAIN_RE, generateStrongPassword } from "./ssh-exec";
import { appBySlug, type AppRow } from "./cpanel-types";

type InstallResult =
  | {
      ok: true;
      id: string;
      domain: string;
      adminUser: string;
      adminPassword: string;
      dbName: string;
      dbUser: string;
      dbPassword: string;
    }
  | { ok: false; error: string };
type Result = { ok: true } | { ok: false; error: string };

const EXCLUSIVE_JOBS = [
  "PROVISION",
  "REINSTALL",
  "DELETE",
  "RESIZE",
  "SUSPEND",
  "UNSUSPEND",
  "SNAPSHOT_ROLLBACK",
  "BACKUP_RESTORE",
] as const;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: { id: true, userId: true, status: true, hostname: true },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function ownedApp(id: string) {
  const user = await requireUser();
  const app = await db.appInstall.findUnique({ where: { id } });
  if (!app) throw new Error("Not found");
  if (app.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, app };
}

function throttle(userId: string, op: string, max: number): string | null {
  const rl = checkRateLimit(`cpanel:app:${op}:${userId}`, { max, windowMs: 60_000 });
  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
}

async function lifecycleBusy(serverId: string): Promise<boolean> {
  const n = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
  });
  return n > 0;
}

function safeError(err: unknown): string {
  const msg = err instanceof Error ? err.message : String(err);
  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
  return msg.slice(0, 300);
}

function rowOut(a: {
  id: string;
  appSlug: string;
  domain: string;
  url: string | null;
  adminUser: string | null;
  status: string;
  error: string | null;
  createdAt: Date;
}): AppRow {
  return {
    id: a.id,
    appSlug: a.appSlug,
    domain: a.domain,
    url: a.url,
    adminUser: a.adminUser,
    status: a.status,
    error: a.error,
    createdAt: a.createdAt.toISOString(),
  };
}

/** Derive a safe DB identifier (letters/digits/underscore, <=32) from a domain. */
function dbIdentFromDomain(domain: string, prefix: string): string {
  const base = domain.replace(/[^a-z0-9]/gi, "_").slice(0, 20);
  const suffix = Math.random().toString(36).slice(2, 6);
  return `${prefix}_${base}_${suffix}`.replace(/_+/g, "_").slice(0, 32);
}

// ---------------------------------------------------------------------------

export async function listApps(
  serverId: string
): Promise<{ ok: true; apps: AppRow[] } | { ok: false; error: string }> {
  try {
    const { server } = await ownedServer(serverId);
    const rows = await db.appInstall.findMany({
      where: { serverId: server.id },
      orderBy: { createdAt: "desc" },
    });
    return { ok: true, apps: rows.map(rowOut) };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function installApp(
  serverId: string,
  appSlug: string,
  domainInput: string,
  adminUserInput?: string
): Promise<InstallResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "install", 6);
    if (limited) return { ok: false, error: limited };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to install an app." };
    if (await lifecycleBusy(server.id))
      return { ok: false, error: "Another server operation is in progress — try again shortly." };

    const app = appBySlug(appSlug);
    if (!app) return { ok: false, error: "Unknown application." };

    const domain = String(domainInput ?? "").toLowerCase().trim().replace(/\.$/, "");
    if (!DOMAIN_RE.test(domain))
      return { ok: false, error: "Enter a valid domain (e.g. blog.example.com) pointed at this server." };

    const adminUser = (String(adminUserInput ?? "admin").replace(/[^a-z0-9_]/gi, "") || "admin").slice(0, 32);

    // Domain must be free of an existing website on this server.
    const dupSite = await db.website.findFirst({ where: { serverId: server.id, domain } });
    if (dupSite) return { ok: false, error: `A website for ${domain} already exists on this server.` };

    const adminPassword = generateStrongPassword(18);
    const dbName = app.engine ? dbIdentFromDomain(domain, "db") : "";
    const dbUser = app.engine ? dbIdentFromDomain(domain, "u") : "";
    const dbPassword = app.engine ? generateStrongPassword(20) : "";

    // Create the primitives + the install record in one transaction.
    const { appRow } = await db.$transaction(async (tx) => {
      const website = await tx.website.create({
        data: {
          userId: user.id,
          serverId: server.id,
          domain,
          docRoot: `/var/www/${domain}`,
          phpVersion: app.php,
          isSubdomain: domain.split(".").length > 2,
          appSlug: app.slug,
          status: "PENDING",
        },
      });
      let database: { id: string } | null = null;
      if (app.engine) {
        database = await tx.vpsDatabase.create({
          data: {
            userId: user.id,
            serverId: server.id,
            engine: app.engine,
            name: dbName,
            dbUser,
            passwordEnc: encryptSecret(dbPassword),
            status: "PENDING",
          },
        });
      }
      const appRow = await tx.appInstall.create({
        data: {
          userId: user.id,
          serverId: server.id,
          appSlug: app.slug,
          domain,
          websiteId: website.id,
          databaseId: database?.id ?? null,
          adminUser,
          adminPassEnc: encryptSecret(adminPassword),
          status: "PENDING",
        },
      });
      return { appRow };
    });

    await db.job.create({ data: { type: "APP_INSTALL", serverId: server.id, payload: { appId: appRow.id } } });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.app.install", detail: `${app.slug} → ${domain} on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    // Credentials returned ONCE.
    return {
      ok: true,
      id: appRow.id,
      domain,
      adminUser,
      adminPassword,
      dbName,
      dbUser,
      dbPassword,
    };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function removeApp(id: string): Promise<Result> {
  try {
    const { user, app } = await ownedApp(id);
    const limited = throttle(user.id, "remove", 10);
    if (limited) return { ok: false, error: limited };
    if (app.status === "INSTALLING") return { ok: false, error: "This app is still installing — try again shortly." };

    // Tear down the provisioned site + database via their own worker jobs, then
    // drop the AppInstall record. The site/db rows carry the SSH cleanup.
    if (app.websiteId) {
      const site = await db.website.findUnique({ where: { id: app.websiteId } });
      if (site) {
        await db.website.update({ where: { id: site.id }, data: { status: "DELETING", appSlug: null } });
        await db.job.create({ data: { type: "WEBSITE_DELETE", serverId: app.serverId, payload: { websiteId: site.id } } });
      }
    }
    if (app.databaseId) {
      const database = await db.vpsDatabase.findUnique({ where: { id: app.databaseId } });
      if (database) {
        await db.vpsDatabase.update({ where: { id: database.id }, data: { status: "DELETING" } });
        await db.job.create({ data: { type: "DB_DELETE", serverId: app.serverId, payload: { databaseId: database.id } } });
      }
    }
    await db.appInstall.delete({ where: { id } });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.app.remove", detail: `${app.appSlug} (${app.domain})` },
    });
    revalidatePath(`/dashboard/servers/${app.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import type { SftpServer } from "../lib/sftp";
import {
  withServerSsh,
  exec,
  execInput,
  assertDomain,
  assertPhp,
  assertPath,
  shellQuote,
  pkgInstallPrefix,
  SETUP_TIMEOUT_MS,
  INSTALL_TIMEOUT_MS,
  QUICK_TIMEOUT_MS,
} from "../lib/ssh-exec";
import type { Job } from "@prisma/client";

/**
 * Control-panel WEBSITE_* handlers.
 *
 * Registered in worker/index.ts:
 *   WEBSITE_CREATE: websiteCreate,
 *   WEBSITE_DELETE: websiteDelete,
 *   WEBSITE_TOGGLE: websiteToggle,
 *   WEBSITE_SSL:    websiteSsl,
 *
 * Ownership + validation happen at enqueue time (lib/actions-websites.ts); these
 * trust `payload.websiteId` but STILL re-validate every value against the strict
 * allowlist in lib/ssh-exec before it can reach a shell.
 *
 * SANDBOX (staging): no SSH — statuses flip with synthetic success, exactly like
 * every other worker feature. On prod the real nginx/php/certbot work runs only
 * when ENABLE_REAL_CPANEL === "1" (belt-and-suspenders, mirroring worker/ssl.ts);
 * otherwise it also takes the simulated-success branch so a fresh prod box can't
 * be mutated until the operator explicitly enables it.
 */

const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[cpanel/web] notify failed", e);
  }
}

async function loadSite(job: Job) {
  const p = (job.payload ?? {}) as { websiteId?: string };
  if (!p.websiteId) throw new Error("website job: missing websiteId");
  const site = await db.website.findUnique({ where: { id: p.websiteId } });
  if (!site) throw new Error(`Website ${p.websiteId} not found`);
  return site;
}

/** Load exactly the SSH fields for a server (mirrors lib/sftp usage). */
async function sshServer(serverId: string): Promise<SftpServer> {
  const s = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      rootPassword: true,
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
  });
  if (!s) throw new Error(`Server ${serverId} not found`);
  return s as SftpServer;
}

/** Render an nginx server block. All values are allowlist-validated by callers. */
function nginxVhost(domain: string, docRoot: string, phpVersion: string | null): string {
  const phpBlock = phpVersion
    ? `
    location ~ \\.php$ {
        include snippets/fastcgi-php.conf;
        fastcgi_pass unix:/run/php/php${phpVersion}-fpm.sock;
    }
`
    : "";
  return `# Managed by Nxeon control panel — do not edit by hand.
server {
    listen 80;
    listen [::]:80;
    server_name ${domain};
    root ${docRoot};
    index index.php index.html index.htm;

    location / {
        try_files $uri $uri/ /index.php?$query_string;
    }
${phpBlock}
    access_log /var/log/nginx/${domain}.access.log;
    error_log /var/log/nginx/${domain}.error.log;
}
`;
}

async function ensureNginx(conn: import("ssh2").Client): Promise<void> {
  const have = await exec(conn, "command -v nginx >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
  if (have.stdout.trim() !== "yes") {
    const prefix = await pkgInstallPrefix(conn);
    const inst = await exec(conn, `${prefix} nginx`, INSTALL_TIMEOUT_MS);
    if (inst.code !== 0) throw new Error(`nginx install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
  }
  // Ensure the sites-available/enabled layout exists (Debian/Ubuntu default).
  await exec(conn, "mkdir -p /etc/nginx/sites-available /etc/nginx/sites-enabled", SETUP_TIMEOUT_MS);
}

async function ensurePhpFpm(conn: import("ssh2").Client, phpVersion: string): Promise<void> {
  assertPhp(phpVersion);
  const svc = `php${phpVersion}-fpm`;
  const have = await exec(conn, `systemctl status ${shellQuote(svc)} >/dev/null 2>&1 && echo yes || echo no`, QUICK_TIMEOUT_MS);
  if (have.stdout.trim() === "yes") return;
  const prefix = await pkgInstallPrefix(conn);
  // php{ver}-fpm + the common extensions apps need.
  const inst = await exec(
    conn,
    `${prefix} php${phpVersion}-fpm php${phpVersion}-mysql php${phpVersion}-cli php${phpVersion}-curl php${phpVersion}-gd php${phpVersion}-mbstring php${phpVersion}-xml`,
    INSTALL_TIMEOUT_MS
  );
  if (inst.code !== 0) throw new Error(`php-fpm install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
  await exec(conn, `systemctl enable --now ${shellQuote(svc)}`, SETUP_TIMEOUT_MS);
}

async function reloadNginx(conn: import("ssh2").Client): Promise<void> {
  const test = await exec(conn, "nginx -t", SETUP_TIMEOUT_MS);
  if (test.code !== 0) throw new Error(`nginx config test failed: ${(test.stderr || test.stdout).trim().slice(0, 200)}`);
  await exec(conn, "systemctl reload nginx || systemctl restart nginx", SETUP_TIMEOUT_MS);
}

// ---------------------------------------------------------------------------

export async function websiteCreate(job: Job): Promise<void> {
  const site = await loadSite(job);
  try {
    if (REAL) {
      assertDomain(site.domain);
      assertPath(site.docRoot);
      if (site.phpVersion) assertPhp(site.phpVersion);
      const server = await sshServer(site.serverId);
      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
      await withServerSsh(server, async (conn) => {
        await ensureNginx(conn);
        if (site.phpVersion) await ensurePhpFpm(conn, site.phpVersion);
        // Docroot + a friendly placeholder index.
        await exec(conn, `mkdir -p ${shellQuote(site.docRoot)} && chown -R www-data:www-data ${shellQuote(site.docRoot)} 2>/dev/null || true`, SETUP_TIMEOUT_MS);
        await execInput(
          conn,
          `cat > ${shellQuote(site.docRoot + "/index.html")}`,
          `<!doctype html><meta charset="utf-8"><title>${site.domain}</title><h1>${site.domain}</h1><p>Your Nxeon-hosted site is live.</p>\n`,
          SETUP_TIMEOUT_MS
        );
        // Write the vhost via STDIN (never as an argv token), enable, reload.
        await execInput(conn, `cat > ${shellQuote(conf)}`, nginxVhost(site.domain, site.docRoot, site.phpVersion), SETUP_TIMEOUT_MS);
        if (site.enabled) {
          await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
        }
        await reloadNginx(conn);
      });
    }
    await db.website.update({ where: { id: site.id }, data: { status: "ACTIVE", error: null } });
    await notify(
      site.userId,
      `Website ${site.domain} is live`,
      REAL ? "Your nginx site is configured and serving." : "Your website was created (sandbox — no real VM was touched).",
      `/dashboard/servers/${site.serverId}?tab=control panel`
    );
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: reason } });
    await notify(site.userId, `Website ${site.domain} failed`, reason.slice(0, 200), `/dashboard/servers/${site.serverId}`);
  }
}

export async function websiteToggle(job: Job): Promise<void> {
  const site = await loadSite(job);
  try {
    if (REAL) {
      assertDomain(site.domain);
      const server = await sshServer(site.serverId);
      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
      await withServerSsh(server, async (conn) => {
        if (site.enabled) await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
        else await exec(conn, `rm -f ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
        await reloadNginx(conn);
      });
    }
    await db.website.update({ where: { id: site.id }, data: { status: site.enabled ? "ACTIVE" : "DISABLED", error: null } });
  } catch (e: any) {
    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 400) } });
  }
}

export async function websiteSsl(job: Job): Promise<void> {
  const site = await loadSite(job);
  try {
    if (REAL) {
      assertDomain(site.domain);
      const server = await sshServer(site.serverId);
      const email = process.env.CERTBOT_EMAIL || "ssl-admin@nxeon.local";
      await withServerSsh(server, async (conn) => {
        const have = await exec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
        if (have.stdout.trim() !== "yes") {
          const prefix = await pkgInstallPrefix(conn);
          const inst = await exec(conn, `${prefix} certbot python3-certbot-nginx`, INSTALL_TIMEOUT_MS);
          if (inst.code !== 0) throw new Error(`certbot install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
        }
        // Use the nginx installer so the vhost is upgraded to 443 in place.
        const run = await exec(
          conn,
          `certbot --nginx -n --agree-tos -m ${shellQuote(email)} -d ${shellQuote(site.domain)} --redirect`,
          INSTALL_TIMEOUT_MS
        );
        const combined = `${run.stdout}\n${run.stderr}`;
        const ok = run.code === 0 && /Congratulations|Successfully|not yet due for renewal|Deploying certificate/i.test(combined);
        if (!ok) throw new Error(`certbot failed: ${combined.trim().slice(0, 300)}`);
      });
    }
    await db.website.update({ where: { id: site.id }, data: { ssl: true, error: null } });
    await notify(
      site.userId,
      `SSL enabled for ${site.domain}`,
      REAL ? "A Let's Encrypt certificate is installed and HTTP redirects to HTTPS." : "SSL enabled (sandbox).",
      `/dashboard/servers/${site.serverId}?tab=control panel`
    );
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    await db.website.update({ where: { id: site.id }, data: { error: reason } });
    await notify(site.userId, `SSL failed for ${site.domain}`, reason.slice(0, 200), `/dashboard/servers/${site.serverId}`);
  }
}

export async function websiteDelete(job: Job): Promise<void> {
  const site = await loadSite(job);
  try {
    if (REAL) {
      assertDomain(site.domain);
      assertPath(site.docRoot);
      const server = await sshServer(site.serverId);
      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
      await withServerSsh(server, async (conn) => {
        await exec(conn, `rm -f ${shellQuote(link)} ${shellQuote(conf)}`, SETUP_TIMEOUT_MS);
        // Remove the docroot ONLY within /var/www (validated path); leave data
        // elsewhere untouched.
        if (site.docRoot.startsWith("/var/www/")) {
          await exec(conn, `rm -rf ${shellQuote(site.docRoot)}`, SETUP_TIMEOUT_MS);
        }
        await reloadNginx(conn).catch(() => {});
      });
    }
    await db.website.delete({ where: { id: site.id } });
  } catch (e: any) {
    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 400) } });
  }
}

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import type { SftpServer } from "../lib/sftp";
import { decryptSecret } from "../lib/crypto-box";
import {
  withServerSsh,
  exec,
  execInput,
  assertIdent,
  assert,
  shellQuote,
  pkgInstallPrefix,
  SETUP_TIMEOUT_MS,
  INSTALL_TIMEOUT_MS,
  QUICK_TIMEOUT_MS,
} from "../lib/ssh-exec";
import type { Job } from "@prisma/client";
import type { Client } from "ssh2";

/**
 * Control-panel DB_CREATE / DB_DELETE handlers (MySQL/MariaDB & PostgreSQL).
 *
 * Registered in worker/index.ts:
 *   DB_CREATE: dbCreate,
 *   DB_DELETE: dbDelete,
 *
 * The generated DB password is decrypted IN MEMORY from `passwordEnc`, applied
 * via the DB client's STDIN (never an argv token — mirrors migrate-real.ts), and
 * then `passwordEnc` is CLEARED. Engine is installed on first use.
 *
 * SANDBOX / non-ENABLE_REAL_CPANEL: no SSH — status flips to ACTIVE and the
 * secret is scrubbed, exactly like the rest of the platform.
 */

const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[cpanel/db] notify failed", e);
  }
}

async function loadDb(job: Job) {
  const p = (job.payload ?? {}) as { databaseId?: string };
  if (!p.databaseId) throw new Error("db job: missing databaseId");
  const row = await db.vpsDatabase.findUnique({ where: { id: p.databaseId } });
  if (!row) throw new Error(`VpsDatabase ${p.databaseId} not found`);
  return row;
}

async function sshServer(serverId: string): Promise<SftpServer> {
  const s = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      rootPassword: true,
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
  });
  if (!s) throw new Error(`Server ${serverId} not found`);
  return s as SftpServer;
}

async function ensureMysql(conn: Client): Promise<void> {
  const have = await exec(conn, "command -v mysql >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
  if (have.stdout.trim() === "yes") return;
  const prefix = await pkgInstallPrefix(conn);
  const inst = await exec(conn, `${prefix} mariadb-server || ${prefix} default-mysql-server`, INSTALL_TIMEOUT_MS);
  if (inst.code !== 0) throw new Error(`MySQL/MariaDB install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
  await exec(conn, "systemctl enable --now mariadb 2>/dev/null || systemctl enable --now mysql", SETUP_TIMEOUT_MS);
}

async function ensurePostgres(conn: Client): Promise<void> {
  const have = await exec(conn, "command -v psql >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
  if (have.stdout.trim() === "yes") return;
  const prefix = await pkgInstallPrefix(conn);
  const inst = await exec(conn, `${prefix} postgresql`, INSTALL_TIMEOUT_MS);
  if (inst.code !== 0) throw new Error(`PostgreSQL install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
  await exec(conn, "systemctl enable --now postgresql", SETUP_TIMEOUT_MS);
}

// ---------------------------------------------------------------------------

export async function dbCreate(job: Job): Promise<void> {
  const row = await loadDb(job);
  try {
    // Validate again before anything can reach a shell/SQL.
    assert(row.engine === "mysql" || row.engine === "postgres", `Unsupported engine: ${row.engine}`);
    assertIdent(row.name, "database name");
    assertIdent(row.dbUser, "database user");

    if (REAL) {
      const password = decryptSecret(row.passwordEnc);
      assert(password, "Generated password is missing or could not be decrypted.");
      const server = await sshServer(row.serverId);
      await withServerSsh(server, async (conn) => {
        if (row.engine === "mysql") {
          await ensureMysql(conn);
          // Root socket auth (Debian/Ubuntu default). Password only in the SQL
          // body, streamed via STDIN — never an argv token.
          const sql =
            `CREATE DATABASE IF NOT EXISTS \`${row.name}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\n` +
            `CREATE USER IF NOT EXISTS '${row.dbUser}'@'localhost' IDENTIFIED BY '${password}';\n` +
            `ALTER USER '${row.dbUser}'@'localhost' IDENTIFIED BY '${password}';\n` +
            `GRANT ALL PRIVILEGES ON \`${row.name}\`.* TO '${row.dbUser}'@'localhost';\n` +
            `FLUSH PRIVILEGES;\n`;
          const r = await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
          if (r.code !== 0) throw new Error(`MySQL create failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
        } else {
          await ensurePostgres(conn);
          // Run as the postgres superuser. Role password only in the SQL body via STDIN.
          const sql =
            `CREATE ROLE "${row.dbUser}" LOGIN PASSWORD '${password}';\n` +
            `CREATE DATABASE "${row.name}" OWNER "${row.dbUser}";\n` +
            `GRANT ALL PRIVILEGES ON DATABASE "${row.name}" TO "${row.dbUser}";\n`;
          const r = await execInput(conn, "sudo -u postgres psql -v ON_ERROR_STOP=1", sql, SETUP_TIMEOUT_MS);
          if (r.code !== 0) throw new Error(`PostgreSQL create failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
        }
      });
    }
    // Scrub the transient secret regardless of path.
    await db.vpsDatabase.update({ where: { id: row.id }, data: { status: "ACTIVE", error: null, passwordEnc: null } });
    await notify(
      row.userId,
      `Database "${row.name}" is ready`,
      REAL ? `Your ${row.engine} database and user are provisioned.` : `Database created (sandbox — no real VM was touched).`,
      `/dashboard/servers/${row.serverId}?tab=control panel`
    );
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    // Even on failure, do not keep the secret around.
    await db.vpsDatabase.update({ where: { id: row.id }, data: { status: "FAILED", error: reason, passwordEnc: null } });
    await notify(row.userId, `Database "${row.name}" failed`, reason.slice(0, 200), `/dashboard/servers/${row.serverId}`);
  }
}

export async function dbDelete(job: Job): Promise<void> {
  const row = await loadDb(job);
  try {
    assert(row.engine === "mysql" || row.engine === "postgres", `Unsupported engine: ${row.engine}`);
    assertIdent(row.name, "database name");
    assertIdent(row.dbUser, "database user");
    if (REAL) {
      const server = await sshServer(row.serverId);
      await withServerSsh(server, async (conn) => {
        if (row.engine === "mysql") {
          const sql =
            `DROP DATABASE IF EXISTS \`${row.name}\`;\n` +
            `DROP USER IF EXISTS '${row.dbUser}'@'localhost';\n` +
            `FLUSH PRIVILEGES;\n`;
          await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
        } else {
          const sql =
            `DROP DATABASE IF EXISTS "${row.name}";\n` +
            `DROP ROLE IF EXISTS "${row.dbUser}";\n`;
          await execInput(conn, "sudo -u postgres psql", sql, SETUP_TIMEOUT_MS);
        }
      });
    }
    await db.vpsDatabase.delete({ where: { id: row.id } });
  } catch (e: any) {
    await db.vpsDatabase.update({ where: { id: row.id }, data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 400) } });
  }
}

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import type { SftpServer } from "../lib/sftp";
import {
  withServerSsh,
  exec,
  execInput,
  assertService,
  assertCronSchedule,
  assert,
  shellQuote,
  SETUP_TIMEOUT_MS,
  QUICK_TIMEOUT_MS,
} from "../lib/ssh-exec";
import { SERVICE_ACTIONS } from "../lib/cpanel-types";
import type { Job } from "@prisma/client";
import type { Client } from "ssh2";

/**
 * Control-panel CRON_SYNC / SERVICE_ACTION handlers.
 *
 * Registered in worker/index.ts:
 *   CRON_SYNC:      cronSync,
 *   SERVICE_ACTION: serviceAction,
 *
 * CRON_SYNC rebuilds a single Nxeon-managed block in root's crontab from all of
 * the server's enabled CronJob rows (removing DELETING ones). The whole crontab
 * body is installed via `crontab -`'s STDIN, so user command lines are never
 * interpolated into a shell we run. Schedules are allowlist-validated.
 *
 * SANDBOX / non-ENABLE_REAL_CPANEL: no SSH — rows just settle to ACTIVE.
 */

const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";
const BEGIN = "# BEGIN NXEON CONTROL PANEL — managed block, do not edit";
const END = "# END NXEON CONTROL PANEL";

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[cpanel/svc] notify failed", e);
  }
}

async function sshServer(serverId: string): Promise<SftpServer> {
  const s = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      rootPassword: true,
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
  });
  if (!s) throw new Error(`Server ${serverId} not found`);
  return s as SftpServer;
}

/** Strip any existing Nxeon-managed block from an existing crontab body. */
function stripManaged(current: string): string {
  const lines = current.split("\n");
  const out: string[] = [];
  let inBlock = false;
  for (const line of lines) {
    if (line.trim() === BEGIN) {
      inBlock = true;
      continue;
    }
    if (line.trim() === END) {
      inBlock = false;
      continue;
    }
    if (!inBlock) out.push(line);
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n").trimEnd();
}

export async function cronSync(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("cron sync: missing serverId");
  const serverId = job.serverId;

  // Remove any DELETING rows first — they must not reappear in the crontab.
  await db.cronJob.deleteMany({ where: { serverId, status: "DELETING" } });

  const rows = await db.cronJob.findMany({ where: { serverId }, orderBy: { createdAt: "asc" } });
  const enabled = rows.filter((r) => r.enabled);

  // Build the managed block (validate every schedule again).
  const blockLines = [BEGIN];
  for (const r of enabled) {
    const sched = assertCronSchedule(r.schedule); // throws on anything unexpected
    if (r.comment) blockLines.push(`# ${r.comment.replace(/[\r\n]/g, " ").slice(0, 80)}`);
    // command validated at enqueue time (no newline/control chars).
    blockLines.push(`${sched} ${r.command}`);
  }
  blockLines.push(END);
  const managedBlock = blockLines.join("\n");

  try {
    if (REAL) {
      const server = await sshServer(serverId);
      await withServerSsh(server, async (conn) => {
        const cur = await exec(conn, "crontab -l 2>/dev/null || true", QUICK_TIMEOUT_MS);
        const base = stripManaged(cur.stdout);
        const body = (base ? base + "\n\n" : "") + managedBlock + "\n";
        // Install the whole crontab via STDIN — user command lines are data here,
        // never a shell we execute.
        const r = await execInput(conn, "crontab -", body, SETUP_TIMEOUT_MS);
        if (r.code !== 0) throw new Error(`crontab install failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
      });
    }
    await db.cronJob.updateMany({ where: { serverId }, data: { status: "ACTIVE", error: null } });
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    await db.cronJob.updateMany({ where: { serverId, status: "PENDING" }, data: { status: "FAILED", error: reason } });
    const first = rows[0];
    if (first) await notify(first.userId, "Cron update failed", reason.slice(0, 200), `/dashboard/servers/${serverId}`);
  }
}

/** Resolve + run a systemctl action for one of the fixed common services. */
async function runService(conn: Client, unit: string, action: string): Promise<void> {
  assertService(unit);
  assert((SERVICE_ACTIONS as readonly string[]).includes(action), `Unsupported action: ${action}`);
  let cmd: string;
  if (unit === "php-fpm") {
    // php-fpm is version-suffixed on Debian/Ubuntu; resolve the real unit name.
    cmd =
      `u=$(systemctl list-unit-files --no-legend 'php*-fpm.service' 2>/dev/null | awk '{print $1}' | head -n1); ` +
      `[ -n "$u" ] || u=php-fpm; systemctl ${action} "$u"`;
  } else if (unit === "mysql") {
    cmd = `systemctl ${action} mariadb 2>/dev/null || systemctl ${action} mysql`;
  } else {
    cmd = `systemctl ${action} ${shellQuote(unit)}`;
  }
  const r = await exec(conn, cmd, SETUP_TIMEOUT_MS);
  if (r.code !== 0) throw new Error(`${action} ${unit} failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
}

export async function serviceAction(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("service action: missing serverId");
  const p = (job.payload ?? {}) as { unit?: string; action?: string };
  const unit = String(p.unit ?? "");
  const action = String(p.action ?? "");
  assertService(unit);
  assert((SERVICE_ACTIONS as readonly string[]).includes(action), `Unsupported action: ${action}`);

  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });

  try {
    if (REAL) {
      const s = await sshServer(job.serverId);
      await withServerSsh(s, async (conn) => runService(conn, unit, action));
    }
    if (server) {
      await notify(
        server.userId,
        `${action[0].toUpperCase()}${action.slice(1)}ed ${unit}`,
        REAL ? `${unit} was ${action}ed on ${server.hostname}.` : `${unit} ${action} (sandbox — no real VM was touched).`,
        `/dashboard/servers/${job.serverId}?tab=control panel`
      );
    }
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 300);
    if (server) await notify(server.userId, `Could not ${action} ${unit}`, reason, `/dashboard/servers/${job.serverId}`);
    throw e; // let the worker mark the job FAILED/retry
  }
}

