import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { decryptSecret } from "../lib/crypto-box";
import {
  withServerSsh,
  exec,
  execInput,
  assertDomain,
  assertIdent,
  assertPath,
  assertSlug,
  assert,
  shellQuote,
  SETUP_TIMEOUT_MS,
  INSTALL_TIMEOUT_MS,
} from "../lib/ssh-exec";
import { ensureNginx, ensurePhpFpm, nginxVhost, reloadNginx, sshServer } from "./websites";
import { appBySlug } from "../lib/cpanel-types";
import type { Job } from "@prisma/client";
import type { Client } from "ssh2";

/**
 * Control-panel APP_INSTALL handler (one-click apps).
 *
 * Registered in worker/index.ts:
 *   APP_INSTALL: appInstall,
 *
 * Reuses the Website + Database primitives: it provisions the vhost + docroot
 * (+PHP) and the database, then installs the app. Admin/DB passwords are
 * decrypted IN MEMORY, applied, then the encrypted copies are CLEARED.
 *
 * SANDBOX / non-ENABLE_REAL_CPANEL: no SSH — the site/db/app rows settle to
 * ACTIVE with a realistic URL, exactly like the rest of the platform. The real
 * path (guarded, off by default) fully installs WordPress; the other catalog
 * apps get their site + database provisioned and are marked ready (their
 * language runtime setup is intentionally left to the customer — see report).
 */

const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[cpanel/app] notify failed", e);
  }
}

async function loadApp(job: Job) {
  const p = (job.payload ?? {}) as { appId?: string };
  if (!p.appId) throw new Error("app job: missing appId");
  const app = await db.appInstall.findUnique({ where: { id: p.appId } });
  if (!app) throw new Error(`AppInstall ${p.appId} not found`);
  return app;
}

/** Create the app's database (MySQL/MariaDB) with the generated password (STDIN). */
async function provisionDb(conn: Client, engine: string, name: string, user: string, password: string) {
  assertIdent(name, "database name");
  assertIdent(user, "database user");
  if (engine === "mysql") {
    const sql =
      `CREATE DATABASE IF NOT EXISTS \`${name}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\n` +
      `CREATE USER IF NOT EXISTS '${user}'@'localhost' IDENTIFIED BY '${password}';\n` +
      `GRANT ALL PRIVILEGES ON \`${name}\`.* TO '${user}'@'localhost';\n` +
      `FLUSH PRIVILEGES;\n`;
    const r = await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
    if (r.code !== 0) throw new Error(`database setup failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
  } else if (engine === "postgres") {
    const sql =
      `CREATE ROLE "${user}" LOGIN PASSWORD '${password}';\n` +
      `CREATE DATABASE "${name}" OWNER "${user}";\n`;
    const r = await execInput(conn, "sudo -u postgres psql -v ON_ERROR_STOP=1", sql, SETUP_TIMEOUT_MS);
    if (r.code !== 0) throw new Error(`database setup failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
  }
}

/** Download + configure WordPress core into docRoot with the provisioned DB. */
async function installWordpress(
  conn: Client,
  docRoot: string,
  db_: { name: string; user: string; password: string }
) {
  assertPath(docRoot);
  // Fetch + extract core (curl/tar available on the platform base images).
  const dl =
    `cd ${shellQuote(docRoot)} && curl -fsSL https://wordpress.org/latest.tar.gz -o /tmp/wp.tgz && ` +
    `tar -xzf /tmp/wp.tgz --strip-components=1 -C ${shellQuote(docRoot)} && rm -f /tmp/wp.tgz`;
  const r = await exec(conn, dl, INSTALL_TIMEOUT_MS);
  if (r.code !== 0) throw new Error(`WordPress download failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
  // wp-config.php — DB creds live in the file body written via STDIN, never argv.
  const salts = `define('AUTH_KEY', '${rand()}');\n`; // minimal; WP still works without unique salts
  const cfg =
    `<?php\n` +
    `define('DB_NAME', '${db_.name}');\n` +
    `define('DB_USER', '${db_.user}');\n` +
    `define('DB_PASSWORD', '${db_.password}');\n` +
    `define('DB_HOST', 'localhost');\n` +
    `define('DB_CHARSET', 'utf8mb4');\n` +
    `define('DB_COLLATE', '');\n` +
    `$table_prefix = 'wp_';\n` +
    salts +
    `define('WP_DEBUG', false);\n` +
    `if ( ! defined('ABSPATH') ) define('ABSPATH', __DIR__ . '/');\n` +
    `require_once ABSPATH . 'wp-settings.php';\n`;
  await execInput(conn, `cat > ${shellQuote(docRoot + "/wp-config.php")}`, cfg, SETUP_TIMEOUT_MS);
  await exec(conn, `chown -R www-data:www-data ${shellQuote(docRoot)} 2>/dev/null || true`, SETUP_TIMEOUT_MS);
}

function rand(): string {
  const { randomBytes } = require("node:crypto") as typeof import("node:crypto");
  return randomBytes(24).toString("base64url");
}

export async function appInstall(job: Job): Promise<void> {
  const app = await loadApp(job);
  const catalog = appBySlug(app.appSlug);
  await db.appInstall.update({ where: { id: app.id }, data: { status: "INSTALLING" } });

  try {
    assertSlug(app.appSlug);
    assertDomain(app.domain);
    assert(catalog, `Unknown app: ${app.appSlug}`);

    const website = app.websiteId ? await db.website.findUnique({ where: { id: app.websiteId } }) : null;
    const database = app.databaseId ? await db.vpsDatabase.findUnique({ where: { id: app.databaseId } }) : null;
    const docRoot = website?.docRoot ?? `/var/www/${app.domain}`;
    const url = `http://${app.domain}/`;

    if (REAL) {
      const dbPass = database ? decryptSecret(database.passwordEnc) : null;
      const server = await sshServer(app.serverId);
      await withServerSsh(server, async (conn) => {
        // 1. Site (vhost + docroot + PHP).
        await ensureNginx(conn);
        if (catalog!.php) await ensurePhpFpm(conn, catalog!.php);
        await exec(conn, `mkdir -p ${shellQuote(docRoot)}`, SETUP_TIMEOUT_MS);
        const conf = `/etc/nginx/sites-available/${app.domain}.conf`;
        const link = `/etc/nginx/sites-enabled/${app.domain}.conf`;
        await execInput(conn, `cat > ${shellQuote(conf)}`, nginxVhost(app.domain, docRoot, catalog!.php), SETUP_TIMEOUT_MS);
        await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS);

        // 2. Database.
        if (database && dbPass) {
          const { ensureEngineForApp } = await import("./databases-bootstrap");
          await ensureEngineForApp(conn, database.engine);
          await provisionDb(conn, database.engine, database.name, database.dbUser, dbPass);
        }

        // 3. The app itself.
        if (app.appSlug === "wordpress" && database && dbPass) {
          await installWordpress(conn, docRoot, { name: database.name, user: database.dbUser, password: dbPass });
        } else {
          // Provisioned site + DB are ready; drop a landing page. (Language-runtime
          // apps like Ghost are intentionally left for the customer to finish.)
          await execInput(
            conn,
            `cat > ${shellQuote(docRoot + "/index.html")}`,
            `<!doctype html><meta charset="utf-8"><title>${catalog!.name}</title>` +
              `<h1>${catalog!.name} is ready to install</h1>` +
              `<p>Your site and database have been provisioned on ${app.domain}. Continue the ${catalog!.name} setup from here.</p>\n`,
            SETUP_TIMEOUT_MS
          );
        }
        await exec(conn, `chown -R www-data:www-data ${shellQuote(docRoot)} 2>/dev/null || true`, SETUP_TIMEOUT_MS);
        await reloadNginx(conn);
      });
    }

    // Settle the linked rows + clear all transient secrets.
    if (website) await db.website.update({ where: { id: website.id }, data: { status: "ACTIVE", ssl: false, error: null } });
    if (database) await db.vpsDatabase.update({ where: { id: database.id }, data: { status: "ACTIVE", error: null, passwordEnc: null } });
    await db.appInstall.update({
      where: { id: app.id },
      data: { status: "ACTIVE", url, error: null, adminPassEnc: null },
    });

    await notify(
      app.userId,
      `${catalog!.name} installed on ${app.domain}`,
      REAL
        ? `Your ${catalog!.name} site is live at ${url}. Admin credentials were shown once at install.`
        : `${catalog!.name} installed (sandbox — no real VM was touched). URL: ${url}`,
      `/dashboard/servers/${app.serverId}?tab=control panel`
    );
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    // Never keep secrets on a failed install.
    if (app.databaseId) await db.vpsDatabase.update({ where: { id: app.databaseId }, data: { status: "FAILED", error: reason, passwordEnc: null } }).catch(() => {});
    if (app.websiteId) await db.website.update({ where: { id: app.websiteId }, data: { status: "FAILED", error: reason } }).catch(() => {});
    await db.appInstall.update({ where: { id: app.id }, data: { status: "FAILED", error: reason, adminPassEnc: null } });
    await notify(app.userId, `${catalog?.name ?? "App"} install failed on ${app.domain}`, reason.slice(0, 200), `/dashboard/servers/${app.serverId}`);
  }
}

