"use client";

import { useState } from "react";

/** Status pill matching the Nxeon theme, coloured by lifecycle state. */
export function StatusPill({ status }: { status: string }) {
  const s = status.toUpperCase();
  const tone =
    s === "ACTIVE"
      ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
      : s === "FAILED"
        ? "border-red-500/30 bg-red-500/10 text-red-300"
        : s === "DISABLED"
          ? "border-slate-500/30 bg-slate-500/10 text-slate-400"
          : "border-amber-500/30 bg-amber-500/10 text-amber-300"; // PENDING/INSTALLING/DELETING
  const label =
    s === "PENDING" ? "Setting up…" : s === "INSTALLING" ? "Installing…" : s === "DELETING" ? "Removing…" : status;
  return (
    <span className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-0.5 text-[11px] font-medium ${tone}`}>
      {(s === "PENDING" || s === "INSTALLING" || s === "DELETING") && (
        <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-current" />
      )}
      {label}
    </span>
  );
}

/** A copy-to-clipboard button (local to the cpanel bundle). */
export function Copy({ text, label }: { text: string; label?: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      className="btn-ghost px-2 py-1 text-xs"
      onClick={() =>
        void navigator.clipboard.writeText(text).then(() => {
          setCopied(true);
          setTimeout(() => setCopied(false), 1500);
        })
      }
    >
      {copied ? "Copied ✓" : label ?? "Copy"}
    </button>
  );
}

/**
 * A "shown once" secret card — the generated password / credentials that will
 * never be retrievable again. Rendered after a create/install succeeds.
 */
export function SecretCard({
  title,
  rows,
  onDismiss,
}: {
  title: string;
  rows: { label: string; value: string; mono?: boolean }[];
  onDismiss: () => void;
}) {
  return (
    <div className="glass mt-4 border-brand-500/30 p-4">
      <div className="mb-3 flex items-center justify-between gap-3">
        <h4 className="text-sm font-semibold text-brand-200">{title}</h4>
        <button type="button" className="btn-ghost px-2 py-1 text-xs" onClick={onDismiss}>
          Dismiss
        </button>
      </div>
      <p className="mb-3 text-xs text-amber-300">
        Save these now — for your security they are shown only once and cannot be retrieved later.
      </p>
      <dl className="space-y-2">
        {rows.map((r) => (
          <div key={r.label} className="flex flex-wrap items-center justify-between gap-2">
            <dt className="text-xs text-slate-400">{r.label}</dt>
            <dd className="flex items-center gap-2">
              <code className="rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1 font-mono text-xs text-slate-100">
                {r.value}
              </code>
              <Copy text={r.value} />
            </dd>
          </div>
        ))}
      </dl>
    </div>
  );
}

/** A centered empty state inside a card. */
export function EmptyState({ title, hint }: { title: string; hint: string }) {
  return (
    <div className="px-4 py-10 text-center">
      <p className="text-sm font-medium text-slate-300">{title}</p>
      <p className="mx-auto mt-1 max-w-md text-xs text-slate-500">{hint}</p>
    </div>
  );
}

/** Skeleton loading rows. */
export function LoadingRows({ rows = 3 }: { rows?: number }) {
  return (
    <div className="space-y-2 p-4">
      {Array.from({ length: rows }).map((_, i) => (
        <div key={i} className="h-10 animate-pulse rounded-xl bg-white/[0.04]" />
      ))}
    </div>
  );
}

/** A card telling the customer the server must be running. */
export function NotRunning({ what }: { what: string }) {
  return (
    <div className="card py-12 text-center">
      <h2 className="font-semibold">{what} unavailable</h2>
      <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
        The control panel works only while your server is{" "}
        <span className="font-medium text-slate-200">running</span>. Start the server to continue.
      </p>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import {
  listWebsites,
  createWebsite,
  toggleWebsite,
  requestWebsiteSsl,
  deleteWebsite,
} from "@/lib/actions-websites";
import { PHP_VERSIONS, type WebsiteRow } from "@/lib/cpanel-types";
import { StatusPill, EmptyState, LoadingRows } from "./shared";

export function WebsitesPanel({ serverId, running }: { serverId: string; running: boolean }) {
  const [sites, setSites] = useState<WebsiteRow[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [domain, setDomain] = useState("");
  const [php, setPhp] = useState<string>("8.3");
  const [formError, setFormError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(async () => {
    const res = await listWebsites(serverId);
    if (res.ok) setSites(res.websites);
    else setError(res.error);
  }, [serverId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  // Poll while any site is transitional so status settles without a manual reload.
  useEffect(() => {
    if (!sites?.some((s) => ["PENDING", "DELETING"].includes(s.status))) return;
    const t = setInterval(() => void refresh(), 4000);
    return () => clearInterval(t);
  }, [sites, refresh]);

  const add = () =>
    start(async () => {
      setFormError(null);
      const res = await createWebsite(serverId, domain, php === "static" ? null : php);
      if (!res.ok) setFormError(res.error);
      else {
        setDomain("");
        await refresh();
      }
    });

  const act = (fn: () => Promise<{ ok: boolean; error?: string }>) =>
    start(async () => {
      setError(null);
      const res = await fn();
      if (!res.ok && res.error) setError(res.error);
      await refresh();
    });

  return (
    <div className="space-y-6">
      <div className="card">
        <h3 className="mb-1 font-semibold">Add a website</h3>
        <p className="mb-4 text-sm text-slate-400">
          Generates an nginx server block with a document root under{" "}
          <code className="font-mono text-xs text-brand-300">/var/www/&lt;domain&gt;</code> and installs the
          chosen PHP-FPM version if needed.
        </p>
        <div className="flex flex-wrap items-end gap-3">
          <div className="grow">
            <label className="label">Domain</label>
            <input
              className="input"
              placeholder="example.com or blog.example.com"
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
              disabled={pending || !running}
            />
          </div>
          <div>
            <label className="label">PHP version</label>
            <select className="input w-44" value={php} onChange={(e) => setPhp(e.target.value)} disabled={pending || !running}>
              {PHP_VERSIONS.map((v) => (
                <option key={v} value={v}>
                  PHP {v}
                </option>
              ))}
              <option value="static">Static (no PHP)</option>
            </select>
          </div>
          <button className="btn-primary" onClick={add} disabled={pending || !running || domain.trim().length < 3}>
            {pending ? "Working…" : "Add website"}
          </button>
        </div>
        {!running && <p className="mt-2 text-xs text-amber-300">Start the server to add websites.</p>}
        {formError && <p className="mt-2 text-sm text-red-400">{formError}</p>}
      </div>

      <div className="card p-0">
        <p className="section-label px-4 pt-4">Websites</p>
        {error && <p className="px-4 pt-3 text-sm text-red-400">{error}</p>}
        {sites === null ? (
          <LoadingRows />
        ) : sites.length === 0 ? (
          <EmptyState title="No websites yet" hint="Add your first domain above to serve a site from this server." />
        ) : (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Domain</th>
                <th>PHP</th>
                <th>SSL</th>
                <th>Status</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {sites.map((s) => {
                const busy = ["PENDING", "DELETING"].includes(s.status);
                return (
                  <tr key={s.id}>
                    <td>
                      <div className="flex items-center gap-2">
                        <a
                          href={`${s.ssl ? "https" : "http"}://${s.domain}`}
                          target="_blank"
                          rel="noreferrer"
                          className="font-medium text-slate-100 hover:text-brand-300"
                        >
                          {s.domain}
                        </a>
                        {s.appSlug && (
                          <span className="rounded-md border border-brand-500/30 bg-brand-500/10 px-1.5 py-0.5 text-[10px] text-brand-200">
                            {s.appSlug}
                          </span>
                        )}
                      </div>
                      <div className="font-mono text-[11px] text-slate-500">{s.docRoot}</div>
                    </td>
                    <td className="text-slate-400">{s.phpVersion ? `PHP ${s.phpVersion}` : "static"}</td>
                    <td>
                      {s.ssl ? (
                        <span className="text-emerald-300">● Secured</span>
                      ) : (
                        <span className="text-slate-500">—</span>
                      )}
                    </td>
                    <td>
                      <div className="flex items-center gap-2">
                        <StatusPill status={s.status} />
                        {!s.enabled && s.status !== "PENDING" && (
                          <span className="text-[11px] text-slate-500">disabled</span>
                        )}
                      </div>
                      {s.error && <div className="mt-1 max-w-xs truncate text-[11px] text-red-400" title={s.error}>{s.error}</div>}
                    </td>
                    <td>
                      <div className="flex items-center justify-end gap-1.5">
                        {s.status === "ACTIVE" && !s.ssl && (
                          <button
                            className="btn-secondary px-2.5 py-1 text-xs"
                            disabled={pending}
                            onClick={() => act(() => requestWebsiteSsl(s.id))}
                          >
                            Enable SSL
                          </button>
                        )}
                        <button
                          className="btn-secondary px-2.5 py-1 text-xs"
                          disabled={pending || busy}
                          onClick={() => act(() => toggleWebsite(s.id))}
                        >
                          {s.enabled ? "Disable" : "Enable"}
                        </button>
                        {!s.appSlug && (
                          <button
                            className="btn-danger px-2.5 py-1 text-xs"
                            disabled={pending || busy}
                            onClick={() => {
                              if (window.confirm(`Delete ${s.domain}? The nginx site and its document root are removed.`))
                                act(() => deleteWebsite(s.id));
                            }}
                          >
                            Delete
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import { listDatabases, createDatabase, deleteDatabase } from "@/lib/actions-databases";
import { DB_ENGINES, DB_ENGINE_LABEL, type DbEngine, type DatabaseRow } from "@/lib/cpanel-types";
import { StatusPill, EmptyState, LoadingRows, SecretCard } from "./shared";

export function DatabasesPanel({ serverId, running }: { serverId: string; running: boolean }) {
  const [rows, setRows] = useState<DatabaseRow[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [engine, setEngine] = useState<DbEngine>("mysql");
  const [name, setName] = useState("");
  const [dbUser, setDbUser] = useState("");
  const [formError, setFormError] = useState<string | null>(null);
  const [secret, setSecret] = useState<{ name: string; dbUser: string; password: string; engine: string } | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(async () => {
    const res = await listDatabases(serverId);
    if (res.ok) setRows(res.databases);
    else setError(res.error);
  }, [serverId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  useEffect(() => {
    if (!rows?.some((r) => ["PENDING", "DELETING"].includes(r.status))) return;
    const t = setInterval(() => void refresh(), 4000);
    return () => clearInterval(t);
  }, [rows, refresh]);

  const create = () =>
    start(async () => {
      setFormError(null);
      const res = await createDatabase(serverId, engine, name, dbUser);
      if (!res.ok) setFormError(res.error);
      else {
        setSecret({ name: res.name, dbUser: res.dbUser, password: res.password, engine });
        setName("");
        setDbUser("");
        await refresh();
      }
    });

  const remove = (r: DatabaseRow) =>
    start(async () => {
      setError(null);
      const res = await deleteDatabase(r.id);
      if (!res.ok) setError(res.error);
      await refresh();
    });

  return (
    <div className="space-y-6">
      <div className="card">
        <h3 className="mb-1 font-semibold">Create a database</h3>
        <p className="mb-4 text-sm text-slate-400">
          Provisions a database and an owner user on your server. The engine is installed automatically on
          first use. The generated password is shown once.
        </p>
        <div className="grid gap-3 sm:grid-cols-2 md:grid-cols-4">
          <div>
            <label className="label">Engine</label>
            <select className="input" value={engine} onChange={(e) => setEngine(e.target.value as DbEngine)} disabled={pending || !running}>
              {DB_ENGINES.map((e) => (
                <option key={e} value={e}>
                  {DB_ENGINE_LABEL[e]}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="label">Database name</label>
            <input className="input" placeholder="app_prod" value={name} onChange={(e) => setName(e.target.value)} disabled={pending || !running} maxLength={32} />
          </div>
          <div>
            <label className="label">Database user</label>
            <input className="input" placeholder="app_user" value={dbUser} onChange={(e) => setDbUser(e.target.value)} disabled={pending || !running} maxLength={32} />
          </div>
          <div className="flex items-end">
            <button className="btn-primary w-full" onClick={create} disabled={pending || !running || !name.trim() || !dbUser.trim()}>
              {pending ? "Working…" : "Create"}
            </button>
          </div>
        </div>
        {!running && <p className="mt-2 text-xs text-amber-300">Start the server to create databases.</p>}
        {formError && <p className="mt-2 text-sm text-red-400">{formError}</p>}
        {secret && (
          <SecretCard
            title={`${DB_ENGINE_LABEL[secret.engine as DbEngine]} database created`}
            rows={[
              { label: "Database", value: secret.name, mono: true },
              { label: "User", value: secret.dbUser, mono: true },
              { label: "Password", value: secret.password, mono: true },
              { label: "Host", value: "localhost", mono: true },
            ]}
            onDismiss={() => setSecret(null)}
          />
        )}
      </div>

      <div className="card p-0">
        <p className="section-label px-4 pt-4">Databases</p>
        {error && <p className="px-4 pt-3 text-sm text-red-400">{error}</p>}
        {rows === null ? (
          <LoadingRows />
        ) : rows.length === 0 ? (
          <EmptyState title="No databases yet" hint="Create your first database above — MySQL/MariaDB or PostgreSQL." />
        ) : (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Name</th>
                <th>Engine</th>
                <th>User</th>
                <th>Status</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => (
                <tr key={r.id}>
                  <td className="font-mono text-xs text-slate-100">{r.name}</td>
                  <td className="text-slate-400">{DB_ENGINE_LABEL[r.engine as DbEngine] ?? r.engine}</td>
                  <td className="font-mono text-xs text-slate-400">{r.dbUser}</td>
                  <td>
                    <StatusPill status={r.status} />
                    {r.error && <div className="mt-1 max-w-xs truncate text-[11px] text-red-400" title={r.error}>{r.error}</div>}
                  </td>
                  <td>
                    <div className="flex justify-end">
                      <button
                        className="btn-danger px-2.5 py-1 text-xs"
                        disabled={pending || ["PENDING", "DELETING"].includes(r.status)}
                        onClick={() => {
                          if (window.confirm(`Delete database "${r.name}" and user "${r.dbUser}"? This cannot be undone.`))
                            remove(r);
                        }}
                      >
                        Delete
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

