      <CronJobs serverId={serverId} running={running} />
    </div>
  );
}

// ---- Resource snapshot ----------------------------------------------------

function ResourceSnapshot({ serverId, running }: { serverId: string; running: boolean }) {
  const [snap, setSnap] = useState<ProcessSnapshot | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    const res = await getProcessSnapshot(serverId);
    if (res.ok) {
      setSnap(res.snapshot);
      setError(null);
    } else setError(res.error);
    setLoading(false);
  }, [serverId]);

  useEffect(() => {
    if (!running) {
      setLoading(false);
      return;
    }
    void refresh();
    const t = setInterval(() => void refresh(), 8000);
    return () => clearInterval(t);
  }, [refresh, running]);

  if (!running) return null;

  return (
    <div className="card">
      <div className="mb-4 flex items-center justify-between">
        <h3 className="font-semibold">Live resource snapshot</h3>
        <span className="text-[11px] text-slate-500">auto-refreshing</span>
      </div>
      {loading && !snap ? (
        <LoadingRows rows={2} />
      ) : error ? (
        <p className="text-sm text-red-400">{error}</p>
      ) : snap ? (
        <>
          <div className="grid gap-4 sm:grid-cols-3">
            <div>
              <div className="mb-1.5 flex justify-between text-sm">
                <span className="text-slate-400">CPU</span>
                <span className="font-semibold">{snap.cpuPct.toFixed(1)}%</span>
              </div>
              <MeterBar value={snap.cpuPct} max={100} />
            </div>
            <div>
              <div className="mb-1.5 flex justify-between text-sm">
                <span className="text-slate-400">Memory</span>
                <span className="font-semibold">
                  {snap.memUsedMB} / {snap.memTotalMB} MB
                </span>
              </div>
              <MeterBar value={snap.memUsedMB} max={snap.memTotalMB || 1} color="#3b82f6" />
            </div>
            <div>
              <div className="mb-1.5 flex justify-between text-sm">
                <span className="text-slate-400">Disk (/)</span>
                <span className="font-semibold">
                  {snap.diskUsedGB} / {snap.diskTotalGB} GB
                </span>
              </div>
              <MeterBar value={snap.diskUsedGB} max={snap.diskTotalGB || 1} color="#10b981" />
            </div>
          </div>
          <div className="mt-3 flex flex-wrap gap-x-6 gap-y-1 text-xs text-slate-400">
            <span>Load: <span className="font-mono text-slate-300">{snap.loadAvg.join(" · ")}</span></span>
            <span>Uptime: <span className="text-slate-300">{fmtUptime(snap.uptimeSec)}</span></span>
          </div>
          <div className="mt-4 overflow-x-auto">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>PID</th>
                  <th>User</th>
                  <th>CPU%</th>
                  <th>MEM%</th>
                  <th>Command</th>
                </tr>
              </thead>
              <tbody>
                {snap.top.map((p) => (
                  <tr key={p.pid}>
                    <td className="font-mono text-xs text-slate-400">{p.pid}</td>
                    <td className="text-slate-400">{p.user}</td>
                    <td className="font-mono text-xs">{p.cpu.toFixed(1)}</td>
                    <td className="font-mono text-xs">{p.mem.toFixed(1)}</td>
                    <td className="max-w-xs truncate font-mono text-xs text-slate-300" title={p.command}>{p.command}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      ) : null}
    </div>
  );
}

// ---- Services -------------------------------------------------------------

function Services({ serverId, running }: { serverId: string; running: boolean }) {
  const [services, setServices] = useState<ServiceStatus[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(async () => {
    const res = await getServiceStatuses(serverId);
    if (res.ok) {
      setServices(res.services);
      setError(null);
    } else setError(res.error);
  }, [serverId]);

  useEffect(() => {
    if (running) void refresh();
  }, [refresh, running]);

  const doAction = (unit: string, action: string) =>
    start(async () => {
      setError(null);
      const res = await serviceAction(serverId, unit, action);
      if (!res.ok) setError(res.error);
      // Give the job a moment, then re-read status.
      setTimeout(() => void refresh(), 2500);
    });

  return (
    <div className="card p-0">
      <div className="flex items-center justify-between px-4 pt-4">
        <p className="section-label">Services</p>
        {running && (
          <button className="btn-ghost px-2 py-1 text-xs" onClick={() => void refresh()}>
            Refresh
          </button>
        )}
      </div>
      {error && <p className="px-4 pt-3 text-sm text-red-400">{error}</p>}
      {!running ? (
        <EmptyState title="Server not running" hint="Start the server to view and control services." />
      ) : services === null ? (
        <LoadingRows />
      ) : (
        <table className="table-shell mt-2">
          <thead>
            <tr>
              <th>Service</th>
              <th>Status</th>
              <th className="text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {services.map((s) => {
              const installed = s.state !== "not-installed";
              return (
                <tr key={s.unit}>
                  <td>
                    <span className="font-medium text-slate-100">{s.label}</span>
                    <span className="ml-2 font-mono text-[11px] text-slate-500">{s.unit}</span>
                  </td>
                  <td>
                    {s.state === "running" ? (
                      <span className="inline-flex items-center gap-1.5 text-emerald-300">
                        <span className="h-1.5 w-1.5 rounded-full bg-emerald-400" /> running
                      </span>
                    ) : s.state === "stopped" ? (
                      <span className="inline-flex items-center gap-1.5 text-slate-400">
                        <span className="h-1.5 w-1.5 rounded-full bg-slate-500" /> stopped
                      </span>
                    ) : s.state === "not-installed" ? (
                      <span className="text-slate-600">not installed</span>
                    ) : (
                      <span className="text-amber-300">unknown</span>
                    )}
                  </td>
                  <td>
                    <div className="flex items-center justify-end gap-1.5">
                      {SERVICE_ACTIONS.map((action) => (
                        <button
                          key={action}
                          className="btn-secondary px-2.5 py-1 text-xs capitalize disabled:opacity-40"
                          disabled={pending || !installed}
                          onClick={() => doAction(s.unit, action)}
                        >
                          {action}
                        </button>
                      ))}
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}

// ---- Cron -----------------------------------------------------------------

function CronJobs({ serverId, running }: { serverId: string; running: boolean }) {
  const [rows, setRows] = useState<CronRow[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [schedule, setSchedule] = useState("0 3 * * *");
  const [command, setCommand] = useState("");
  const [comment, setComment] = useState("");
  const [formError, setFormError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(async () => {
    const res = await listCronJobs(serverId);
    if (res.ok) setRows(res.cron);
    else setError(res.error);
  }, [serverId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  useEffect(() => {
    if (!rows?.some((r) => ["PENDING", "DELETING"].includes(r.status))) return;
    const t = setInterval(() => void refresh(), 4000);
    return () => clearInterval(t);
  }, [rows, refresh]);

  const add = () =>
    start(async () => {
      setFormError(null);
      const res = await createCronJob(serverId, schedule, command, comment || undefined);
      if (!res.ok) setFormError(res.error);
      else {
        setCommand("");
        setComment("");
        await refresh();
      }
    });

  const act = (fn: () => Promise<{ ok: boolean; error?: string }>) =>
    start(async () => {
      setError(null);
      const res = await fn();
      if (!res.ok && res.error) setError(res.error);
      await refresh();
    });

  return (
    <div className="space-y-6">
      <div className="card">
        <h3 className="mb-1 font-semibold">Add a cron job</h3>
        <p className="mb-4 text-sm text-slate-400">
          Schedules run as <code className="font-mono text-xs text-brand-300">root</code> in your VPS crontab.
        </p>
        <div className="grid gap-3">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="label">Schedule</label>
              <input className="input w-40 font-mono" value={schedule} onChange={(e) => setSchedule(e.target.value)} disabled={pending || !running} />
            </div>
            <div>
              <label className="label">Preset</label>
              <select className="input w-52" value="" onChange={(e) => e.target.value && setSchedule(e.target.value)} disabled={pending || !running}>
                <option value="">Choose…</option>
                {CRON_PRESETS.map((p) => (
                  <option key={p.value} value={p.value}>
                    {p.label} ({p.value})
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="label">Label (optional)</label>
              <input className="input w-48" value={comment} onChange={(e) => setComment(e.target.value)} disabled={pending || !running} maxLength={80} placeholder="nightly backup" />
            </div>
          </div>
          <div>
            <label className="label">Command</label>
            <input className="input font-mono" placeholder="/usr/bin/certbot renew --quiet" value={command} onChange={(e) => setCommand(e.target.value)} disabled={pending || !running} maxLength={500} />
          </div>
          <div>
            <button className="btn-primary" onClick={add} disabled={pending || !running || command.trim().length < 2}>
              {pending ? "Working…" : "Add cron job"}
            </button>
          </div>
        </div>
        {!running && <p className="mt-2 text-xs text-amber-300">Start the server to manage cron jobs.</p>}
        {formError && <p className="mt-2 text-sm text-red-400">{formError}</p>}
      </div>

      <div className="card p-0">
        <p className="section-label px-4 pt-4">Cron jobs</p>
        {error && <p className="px-4 pt-3 text-sm text-red-400">{error}</p>}
        {rows === null ? (
          <LoadingRows />
        ) : rows.length === 0 ? (
          <EmptyState title="No cron jobs" hint="Schedule recurring commands — backups, cert renewals, cleanup." />
        ) : (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Schedule</th>
                <th>Command</th>
                <th>Status</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => {
                const busy = ["PENDING", "DELETING"].includes(r.status);
                return (
                  <tr key={r.id} className={r.enabled ? "" : "opacity-60"}>
                    <td className="font-mono text-xs text-slate-100">{r.schedule}</td>
                    <td>
                      {r.comment && <div className="text-[11px] text-slate-500">{r.comment}</div>}
                      <div className="max-w-md truncate font-mono text-xs text-slate-300" title={r.command}>{r.command}</div>
                    </td>
                    <td>
                      <StatusPill status={r.status} />
                      {!r.enabled && r.status !== "PENDING" && <span className="ml-1 text-[11px] text-slate-500">paused</span>}
                      {r.error && <div className="mt-1 max-w-xs truncate text-[11px] text-red-400" title={r.error}>{r.error}</div>}
                    </td>
                    <td>
                      <div className="flex items-center justify-end gap-1.5">
                        <button className="btn-secondary px-2.5 py-1 text-xs" disabled={pending || busy} onClick={() => act(() => toggleCronJob(r.id))}>
                          {r.enabled ? "Pause" : "Resume"}
                        </button>
                        <button
                          className="btn-danger px-2.5 py-1 text-xs"
                          disabled={pending || busy}
                          onClick={() => {
                            if (window.confirm("Delete this cron job?")) act(() => deleteCronJob(r.id));
                          }}
                        >
                          Delete
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { WebsitesPanel } from "./WebsitesPanel";
import { DatabasesPanel } from "./DatabasesPanel";
import { AppsPanel } from "./AppsPanel";
import { CronServicesPanel } from "./CronServicesPanel";

const SUBTABS = [
  { key: "websites", label: "Websites & PHP" },
  { key: "databases", label: "Databases" },
  { key: "apps", label: "One-click apps" },
  { key: "services", label: "Cron & Services" },
] as const;

/**
 * Grouped "Control panel" tab on the server detail page — a cPanel/Plesk-style
 * manager for the customer's own VPS, themed to match Nxeon. Keeps the four
 * bundles behind a single main tab with lightweight inner tabs so the page stays
 * readable. Each panel loads its own data client-side (loading/empty/error
 * states throughout) via the sandbox-gated server actions.
 */
export function ControlPanel({ serverId, running }: { serverId: string; running: boolean }) {
  const [tab, setTab] = useState<string>("websites");

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap gap-1.5">
        {SUBTABS.map((t) => {
          const active = tab === t.key;
          return (
            <button
              key={t.key}
              type="button"
              onClick={() => setTab(t.key)}
              className={`rounded-xl px-3.5 py-1.5 text-sm font-medium transition-colors ${
                active
                  ? "bg-white/[0.08] text-white ring-1 ring-inset ring-brand-500/40"
                  : "text-slate-400 hover:bg-white/[0.04] hover:text-white"
              }`}
            >
              {t.label}
            </button>
          );
        })}
      </div>

      <div className="animate-fade-up">
        {tab === "websites" && <WebsitesPanel serverId={serverId} running={running} />}
        {tab === "databases" && <DatabasesPanel serverId={serverId} running={running} />}
        {tab === "apps" && <AppsPanel serverId={serverId} running={running} />}
        {tab === "services" && <CronServicesPanel serverId={serverId} running={running} />}
      </div>
    </div>
  );
}

