export function generateStrongPassword(len = 20): string {
  // Imported lazily so this module stays free of a top-level node:crypto need in
  // any edge context; in practice it's always server/worker.
  const { randomBytes } = require("node:crypto") as typeof import("node:crypto");
  return randomBytes(len * 2)

